"""Content of DIRAC16COMPLEX (Markdown + LaTeX): the Dirac equation of the 16-component quantized field dirac16complex on
7+1 spacetime with real 16x16 Dirac matrices, its chiral 8-component form, and the 16-component and chiral Kohn-Sham
theories of the self-coupled field (sections 7-10 of 7+1.nb).  Every equation used is written in this document."""
import sympy as sp
from docgen import Doc, pmat
from collections import OrderedDict
from doc_common import all_checks

def num(x, n=12):
    """LaTeX decimal string of x with n significant digits"""
    x = sp.Float(sp.N(sp.sympify(str(x)) if not isinstance(x, sp.Basic) else x, 40), 30)
    if x == 0: return '0'
    e = int(sp.floor(sp.log(abs(x), 10)))
    if -3 <= e <= 4:
        s = sp.N(x, n)
        t = ('%.' + str(max(n - 1 - e, 0)) + 'f') % float(s) if n <= 15 else str(s)
        return t
    m = x / sp.Integer(10)**e
    t = ('%.' + str(n - 1) + 'f') % float(sp.N(m, n))
    return t + r'\times10^{%d}' % e

def build(D):
    nbinfo = D['nb']; log = D['log']; ref = D['ref']
    n79 = len(D['checks79']); nall = len(all_checks(D))
    d = Doc('dirac16complex: the Dirac equation and Kohn–Sham theory of a 16-component fermion field on 7+1 spacetime',
            'Real 16×16 Dirac matrices, the chiral 8-component equations, and the 16-component and chiral Kohn–Sham theories of '
            'the self-coupled field — sections 7–10 of the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1), evaluated ' + log.get('finished', ''),
             'Document generated by tools/make_docs.py on ' + D['today']],
            'This document defines and verifies (i) the Dirac equation of a 16-component quantized fermion field named '
            'dirac16complex on the real 7+1 spacetime (one time coordinate $x_0$, seven space coordinates $x_1,\\dots,x_7$), whose '
            'components are complex-valued anticommuting (Grassmann) operators, with eight anticommuting REAL 16×16 Dirac '
            'matrices; (ii) the chiral projections that split the 16-component equation into two 8-component equations, coupled '
            'by the mass; (iii) a 16-component Kohn–Sham theory of the field coupled to itself through scalar, pseudoscalar, '
            'vector and axial-vector contact interactions; (iv) the chiral (8+8-component) form of that Kohn–Sham theory; '
            '(v) worked examples: uniform matter in the Hartree and Hartree–Fock approximations, with saturation and the '
            'Hugenholtz–Van Hove theorem, and the chiral vacuum with the Dirac sea (spontaneous chiral symmetry breaking). '
            'Sections 7–9 of 7+1.nb contain %d checks and the whole notebook %d; all are True, and an independent Python program '
            'reproduces every identity and every number.' % (n79, nall))

    # =====================================================================================================
    d.h1('1. Results at a glance')
    d.p('**Real Dirac matrices.** With the real 8×8 octonion matrices $\\tau^{O}_i$ ($i=1,\\dots,7$; antisymmetric, '
        '$(\\tau^{O}_i)^2=-1_8$, mutually anticommuting; section 2.3) the eight Dirac matrices are')
    d.eq(r'\Gamma_0=\begin{pmatrix}0&1_8\\1_8&0\end{pmatrix},\qquad \Gamma_i=\begin{pmatrix}\tau^{O}_i&0\\0&-\tau^{O}_i\end{pmatrix},\qquad '
         r'\Gamma_A\Gamma_B+\Gamma_B\Gamma_A=2\,\eta_{AB}\,1_{16},\qquad \eta=\mathrm{diag}(+1,-1,\dots,-1).')
    d.p('Every entry is $0$ or $\\pm1$. These are the only real choice: with the opposite sign convention (time squaring to $-1$) '
        'no real 16×16 matrices exist (section 3.3).')
    d.p('**The Dirac equation of dirac16complex** $\\psi=(\\psi_1,\\dots,\\psi_{16})$, with $\\Gamma^A=\\eta^{AA}\\Gamma_A$ and '
        '$\\partial_A=\\partial/\\partial x_A$:')
    d.eq(r'\big(i\,\Gamma^A\partial_A-m\big)\psi=0\qquad\Longleftrightarrow\qquad i\,\partial_0\psi=\big(-i\,\alpha_i\,\partial_i+\beta\,m\big)\psi,'
         r'\qquad \beta=\Gamma^0,\ \ \alpha_i=\Gamma^0\Gamma^i=\begin{pmatrix}0&\tau^{O}_i\\-\tau^{O}_i&0\end{pmatrix}.')
    d.p('**Two coupled 8-component equations.** There is no real chirality matrix in 7+1 dimensions; the chirality '
        '$\\chi=i\\,\\Gamma_0\\Gamma_1\\cdots\\Gamma_7$ is complex, and so are the chiral projections $P_{L,R}=\\tfrac12(1_{16}\\mp\\chi)$. '
        'With $\\phi_L=(\\psi_{\\uparrow}+i\\psi_{\\downarrow})/\\sqrt2$ and $\\phi_R=(i\\psi_{\\uparrow}+\\psi_{\\downarrow})/\\sqrt2$ '
        '($\\psi_\\uparrow,\\psi_\\downarrow$ the upper and lower 8 components):')
    d.align([r'\big(i\,\partial_0+\tau^{O}_i\,\partial_i\big)\,\phi_L&=m\,\phi_R,',
             r'\big(i\,\partial_0-\tau^{O}_i\,\partial_i\big)\,\phi_R&=m\,\phi_L .'])
    d.p('Only the real $\\tau^{O}_i$ appear; the mass couples the two 8-component fields, which decouple for $m=0$.')
    d.p('**16-component Kohn–Sham equations** of the field coupled to itself (couplings $g_S,g_P,g_V,g_A$):')
    d.align([r'h_{\rm KS}\,\varphi_k&=\varepsilon_k\,\varphi_k,',
             r'h_{\rm KS}&=\alpha_i\big(-i\partial_i+\mathcal V_i\big)+\beta\big(m+\mathcal S\big)+\mathcal V_0+\beta\,i\chi\,\mathcal P+\chi\,\mathcal A_0+\alpha_i\chi\,\mathcal A_i,',
             r'\mathcal S&=\mathsf s+g_S\rho_S+\frac{\delta E_{xc}}{\delta\rho_S},\qquad \mathcal P=\mathsf p+g_P\rho_P+\frac{\delta E_{xc}}{\delta\rho_P},',
             r'\mathcal V_A&=\mathsf v_A+g_Vj_A+\frac{\delta E_{xc}}{\delta j^A},\qquad \mathcal A_A=\mathsf a_A+g_Aj_{5A}+\frac{\delta E_{xc}}{\delta j_5^A}.'])
    d.p('**Chiral Kohn–Sham equations** (8+8 components), with the complex Kohn–Sham mass $\\mathcal M=m+\\mathcal S+i\\mathcal P$ and '
        '$\\mathcal V^{L,R}_A=\\mathcal V_A\\mp\\mathcal A_A$, $\\sigma_i=i\\tau^{O}_i$:')
    d.align([r'\big[\mathcal V^L_0-\sigma_i\big(-i\partial_i+\mathcal V^L_i\big)\big]\varphi_L+\mathcal M\,\varphi_R&=\varepsilon\,\varphi_L,',
             r'\mathcal M^*\,\varphi_L+\big[\mathcal V^R_0+\sigma_i\big(-i\partial_i+\mathcal V^R_i\big)\big]\varphi_R&=\varepsilon\,\varphi_R .'])
    hs = D['hs']; nj = D['nj']
    d.p('**Examples.** Uniform matter with $g_S=-10^5$, $g_V=10^4$ (units $m=1$, no Dirac sea) saturates at $k_F=%s$ with '
        '$E/A-m=%s$ and $m^*=%s$; the Hugenholtz–Van Hove theorem $E/A=\\varepsilon_F$ holds there to 25 digits. With the Dirac '
        'sea, cutoff $\\Lambda=1$ and $g_S=g_P=\\tfrac65g_c$, $g_c=-90\\pi^4/\\Lambda^6$, chiral symmetry breaks spontaneously: '
        '$|\\mathcal M|=%s$.' % (num(hs['kF0']), num(hs['E/A - m']), num(hs['mstar']), num(nj['|M| (m = 0)'])))
    d.p('**Verification.** %d checks in sections 7–9 of 7+1.nb (%d in the whole notebook), all True, no message cells; '
        'independently, tools/ref_dirac16.py (Python, sympy/mpmath/numpy) passes %d checks and reproduces all printed numbers '
        'to 17 digits (section 11).' % (n79, nall, len(D['ref_bool'])))
    for f in SECTIONS: f(d, D)
    return d

SECTIONS = []
def section(f):
    SECTIONS.append(f); return f

# =========================================================================================================
@section
def sec2(d, D):
    d.h1('2. Spacetime, units, notation')
    d.h2('2.1 Coordinates and metric')
    d.p('Units $\\hbar=c=1$. The coordinates are the eight real numbers $X=(x_0,x_1,\\dots,x_7)$ (Mathematica: '
        '`X = {x0, x1, x2, x3, x4, x5, x6, x7}`): $x_0$ is time (the direction of the octonion unit $e_0=1$), $x_1,x_2,x_3$ are '
        'ordinary 3-space and $x_4,\\dots,x_7$ are four auxiliary space-like dimensions. The metric is')
    d.eq(r'\eta_{AB}=\eta^{AB}=\mathrm{diag}(+1,-1,-1,-1,-1,-1,-1,-1),\qquad a\cdot b=\eta_{AB}\,a^Ab^B=a^0b^0-\sum_{i=1}^{7}a^ib^i,')
    d.p('the real part of the octonion square, $\\mathrm{Re}(x\\,x)=x_0^2-x_1^2-\\dots-x_7^2$. Indices $A,B,K,L\\in\\lbrace0,\\dots,7\\rbrace$ '
        'are raised and lowered with $\\eta$; $i,j\\in\\lbrace1,\\dots,7\\rbrace$ are space indices; repeated indices are summed. '
        '$\\partial_A=\\partial/\\partial x_A$ (the coordinates are $x^A=x_A$ as symbols, and $\\partial_A$ acts on them as '
        '$\\partial_Ax^B=\\delta_A^B$). A space vector is written with an arrow, $\\vec p=(p^1,\\dots,p^7)$, '
        '$\\vec p\\cdot\\vec x=\\sum_ip^ix_i$, $\\vec p^{\\,2}=\\sum_i(p^i)^2$. The wave (d’Alembert) operator is')
    d.eq(r'\Box=\eta^{AB}\partial_A\partial_B=\partial_0^2-\partial_1^2-\dots-\partial_7^2 .')
    d.h2('2.2 Matrix notation')
    d.p('$1_n$ is the $n\\times n$ identity, $M^{\\mathsf T}$ the transpose, $M^\\dagger=\\overline{M}^{\\mathsf T}$ the Hermitian '
        'conjugate, $\\overline{z}$ or $z^*$ the complex conjugate, $\\mathrm{tr}$ the trace, $\\delta_{ij}$ the Kronecker delta and '
        '$\\lbrace X,Y\\rbrace=XY+YX$. A 16×16 matrix is often written as 2×2 blocks of 8×8 matrices, '
        '$\\left(\\begin{smallmatrix}a&b\\\\c&d\\end{smallmatrix}\\right)$, and a 16-component column as $(\\psi_\\uparrow;\\psi_\\downarrow)$ '
        '(upper and lower 8 components). $e_s$ ($s=1,\\dots,8$) is the $s$-th unit column of length 8. Mathematica names are '
        'given in `typewriter`; Mathematica lists are 1-based, so $\\eta_{AB}$ is `η17[[A+1, B+1]]` in the notebook.')
    d.h2('2.3 The real 8×8 matrices $\\tau^{O}_i$')
    d.p('The building blocks are the seven real 8×8 matrices $\\tau^{O}_1,\\dots,\\tau^{O}_7$ of 7+1.nb (`τO[i]`; $\\tau^{O}_0=1_8$). '
        'They are the left multiplications by the imaginary octonion units $e_1,\\dots,e_7$ written in a spinor basis, and they '
        'satisfy')
    d.eq(r'(\tau^{O}_i)^{\mathsf T}=-\tau^{O}_i,\qquad \tau^{O}_i\tau^{O}_j+\tau^{O}_j\tau^{O}_i=-2\,\delta_{ij}\,1_8,\qquad '
         r'\tau^{O}_1\tau^{O}_2\cdots\tau^{O}_7=1_8\qquad(i,j=1,\dots,7).')
    tO = D['tauO']
    d.eq(r'\tau^{O}_1=%s,\quad \tau^{O}_2=%s,' % (pmat(tO[1]), pmat(tO[2])))
    d.eq(r'\tau^{O}_3=%s,\quad \tau^{O}_4=%s,' % (pmat(tO[3]), pmat(tO[4])))
    d.eq(r'\tau^{O}_5=%s,\quad \tau^{O}_6=%s,' % (pmat(tO[5]), pmat(tO[6])))
    d.eq(r'\tau^{O}_7=%s.' % pmat(tO[7]))
    d.p('**Where they come from.** 7+1.nb builds them from the real split-octonion matrices $\\tau_A$ of the notebook 4+4.nb: '
        '$\\tau^{O}_i=\\tau_i$ for $i=1,2,3$ and $\\tau^{O}_i=\\tau_i\\,\\sigma$ for $i=4,\\dots,7$, where '
        '$\\sigma=\\tau_1\\tau_2\\tau_3=\\left(\\begin{smallmatrix}0&1_4\\\\1_4&0\\end{smallmatrix}\\right)$ commutes with '
        '$\\tau_1,\\tau_2,\\tau_3$, anticommutes with $\\tau_4,\\dots,\\tau_7$ and squares to $1_8$, so that '
        '$(\\tau_k\\sigma)^2=-\\tau_k^2\\sigma^2=-1_8$ for $k=4,\\dots,7$ (the split matrices $\\tau_4,\\dots,\\tau_7$ square to $+1_8$). '
        'Explicitly, the four split matrices are')
    t = D['tau']
    d.eq(r'\tau_4=%s,\quad \tau_5=%s,' % (pmat(t[4]), pmat(t[5])))
    d.eq(r'\tau_6=%s,\quad \tau_7=%s,' % (pmat(t[6]), pmat(t[7])))
    d.p('and $\\tau_1,\\tau_2,\\tau_3$ equal $\\tau^{O}_1,\\tau^{O}_2,\\tau^{O}_3$ displayed above.')
    d.p('With $\\sigma_i=i\\,\\tau^{O}_i$ one obtains seven Hermitian 8×8 matrices with $\\sigma_i\\sigma_j+\\sigma_j\\sigma_i=2\\delta_{ij}1_8$: '
        'the analogues of the Pauli matrices for seven space dimensions (Mathematica `σW[i]`). For a space vector, '
        '$\\tau^{O}\\cdot\\vec p=\\sum_ip^i\\tau^{O}_i$ and $\\sigma\\cdot\\vec p=\\sum_ip^i\\sigma_i$, with '
        '$(\\tau^{O}\\cdot\\vec p)^2=-\\vec p^{\\,2}1_8$ and $(\\sigma\\cdot\\vec p)^2=\\vec p^{\\,2}1_8$.')

# =========================================================================================================
@section
def sec3(d, D):
    d.h1('3. The eight real Dirac matrices')
    d.h2('3.1 Definition and Clifford relation')
    d.p('The Dirac matrices are the real 16×16 matrices $\\Gamma_A$ (`Γ17[A]`, section 4.2 of 7+1.nb):')
    d.eq(r'\Gamma_0=\begin{pmatrix}0&1_8\\1_8&0\end{pmatrix},\qquad \Gamma_i=\begin{pmatrix}\tau^{O}_i&0\\0&(\tau^{O}_i)^{\mathsf T}\end{pmatrix}'
         r'=\begin{pmatrix}\tau^{O}_i&0\\0&-\tau^{O}_i\end{pmatrix}\quad(i=1,\dots,7),')
    d.eq(r'\Gamma_A\Gamma_B+\Gamma_B\Gamma_A=2\,\eta_{AB}\,1_{16}\qquad(A,B=0,\dots,7):\qquad \Gamma_0^2=+1_{16},\quad \Gamma_i^2=-1_{16}.')
    d.p('Every entry is $0$ or $\\pm1$. In terms of the 16×16 Dirac matrices of 4+4.nb,')
    d.align([r'T_A&=\begin{pmatrix}0&\bar\tau_A\\ \tau_A&0\end{pmatrix},\qquad \bar\tau_0=1_8,\quad \bar\tau_A=\sigma\,\tau_A^{\mathsf T}\sigma\ (A=1,\dots,7),',
             r'T_AT_B+T_BT_A&=2\,\eta^{(4,4)}_{AB}\,1_{16},\qquad \eta^{(4,4)}=\mathrm{diag}(+1,+1,+1,+1,-1,-1,-1,-1),'])
    d.p('(with $\\tau_A$ and $\\sigma$ of section 2.3) they are $\\Gamma_0=T_0$, $\\Gamma_i=T_0T_i$ ($i=1,2,3$) and '
        '$\\Gamma_k=T_0T_kT_4T_5T_6T_7$ ($k=4,\\dots,7$). The index is raised with $\\eta$:')
    d.eq(r'\Gamma^A=\eta^{AA}\,\Gamma_A:\qquad \Gamma^0=\Gamma_0,\qquad \Gamma^i=-\Gamma_i,\qquad \Gamma^A\Gamma_A=8\cdot1_{16}.')
    d.p('Because $\\Gamma_0$ is symmetric, the $\\Gamma_i$ are antisymmetric and all are real,')
    d.eq(r'\big(\Gamma^A\big)^\dagger=\big(\Gamma^A\big)^{\mathsf T}=\Gamma^0\,\Gamma^A\,\Gamma^0 .')
    d.p('The 256 ordered products $\\Gamma_K=\\Gamma_{A_1}\\Gamma_{A_2}\\cdots\\Gamma_{A_k}$ ($K=\\lbrace A_1<\\dots<A_k\\rbrace\\subseteq\\lbrace0,\\dots,7\\rbrace$, '
        '$\\Gamma_\\emptyset=1_{16}$) are linearly independent, so $\\Gamma_A$ generate the full real Clifford algebra '
        '$Cl(1,7)\\cong\\mathbb R(16)$ of the quadratic form $Q(v)=v\\cdot v$: $\\big(\\sum_Av^A\\Gamma_A\\big)^2=Q(v)\\,1_{16}$.')
    d.h2('3.2 The Dirac $\\alpha$, $\\beta$ and the volume element $\\omega$')
    d.align([r'\beta&=\Gamma^0=\begin{pmatrix}0&1_8\\1_8&0\end{pmatrix},\qquad '
             r'\alpha_i=\Gamma^0\Gamma^i=-\Gamma_0\Gamma_i=\begin{pmatrix}0&\tau^{O}_i\\-\tau^{O}_i&0\end{pmatrix}\quad(i=1,\dots,7),',
             r'\alpha_i\alpha_j+\alpha_j\alpha_i&=2\,\delta_{ij}\,1_{16},\qquad \alpha_i\beta+\beta\alpha_i=0,\qquad \beta^2=1_{16},\qquad '
             r'\alpha_i^{\mathsf T}=\alpha_i,\ \ \beta^{\mathsf T}=\beta\ \ (\text{real symmetric}),',
             r'\omega&=\Gamma_0\Gamma_1\cdots\Gamma_7=\begin{pmatrix}0&-1_8\\1_8&0\end{pmatrix},\qquad \omega^2=-1_{16},\qquad '
             r'\omega\,\Gamma_A=-\Gamma_A\,\omega\quad(A=0,\dots,7).'])
    d.p('In the notebook: $\\beta$ = `βD`, $\\alpha_i$ = `αD[i]`, $\\omega$ = `ω17` = `Γ17[8]`.')
    d.h2('3.3 Why real Dirac matrices force the convention $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$')
    d.p('The opposite overall sign, $\\eta\'=-\\eta=\\mathrm{diag}(-1,+1,\\dots,+1)$ (time squaring to $-1$), generates the Clifford '
        'algebra $Cl(7,1)\\cong\\mathbb H(8)$, which has NO real 16×16 realization: if real $R_A$ with '
        '$R_AR_B+R_BR_A=2\\eta\'_{AB}1_{16}$ existed, then, $Cl_8(\\mathbb C)\\cong\\mathbb C(16)$ having a single irreducible module, '
        '$R_A=T\\,(i\\Gamma_A)\\,T^{-1}$ for an invertible complex $T$; reality of $R_A$ gives $Y\\,\\overline{(i\\Gamma_A)}=(i\\Gamma_A)\\,Y$ '
        'with $Y=T^{-1}\\overline T$ and $Y\\overline Y=1_{16}$. Because the $\\Gamma_A$ are real, $\\overline{(i\\Gamma_A)}=-i\\Gamma_A$, so '
        '$Y\\Gamma_A=-\\Gamma_AY$ for all $A$; then $Y\\omega$ commutes with every $\\Gamma_A$ and, by Schur’s lemma (the commutant of the '
        'irreducible $\\mathbb C(16)$ is $\\mathbb C\\,1_{16}$), $Y=c\\,\\omega$ with $c\\in\\mathbb C$ (the real solutions, computed in 7+1.nb, '
        'are $\\mathbb R\\,\\omega$). But then $Y\\overline Y=|c|^2\\omega^2=-|c|^2\\,1_{16}\\neq1_{16}$ — a contradiction. Reordering, renaming or '
        're-signing indices does not change the signature, so it cannot help. Hence $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$ is the 7+1 '
        'convention with real 16×16 Dirac matrices, and the Dirac matrices of this document are real.')

# =========================================================================================================
@section
def sec4(d, D):
    d.h1('4. The field dirac16complex and its Dirac equation')
    d.h2('4.1 The field')
    d.p('The quantized fermion field is the column of 16 components (Mathematica: `dirac16complex = Table[ψ16[a] @@ X, {a, 1, 16}]`)')
    d.eq(r'\psi(x)\equiv\texttt{dirac16complex}(x)=\big(\psi_1(x),\dots,\psi_{16}(x)\big)^{\mathsf T},\qquad x=(x_0,x_1,\dots,x_7).')
    d.p('Each component is a complex (non-Hermitian, $\\psi_a^\\dagger\\neq\\psi_a$) Grassmann-odd operator field. At equal times')
    d.eq(r'\psi_a(x_0,\vec x)\,\psi_b(x_0,\vec y)+\psi_b(x_0,\vec y)\,\psi_a(x_0,\vec x)=0,\qquad '
         r'\psi_a(x_0,\vec x)\,\psi_b^\dagger(x_0,\vec y)+\psi_b^\dagger(x_0,\vec y)\,\psi_a(x_0,\vec x)=\delta_{ab}\,\delta^7(\vec x-\vec y),')
    d.p('in particular $\\psi_a^2=0$ (section 6). The Dirac adjoint is $\\bar\\psi=\\psi^\\dagger\\Gamma^0$.')
    d.h2('4.2 The Dirac equation and the Klein–Gordon equation')
    d.eq(r'\big(i\,\Gamma^A\partial_A-m\big)\psi=0\qquad\text{i.e.}\qquad i\,\Gamma_0\,\partial_0\psi-i\sum_{i=1}^{7}\Gamma_i\,\partial_i\psi-m\,\psi=0 .')
    d.p('The matrices are real; the factor $i$ in front of them is unavoidable. With real $\\Gamma_A$ the first-order operator squares '
        'to $+\\Box$: $(\\Gamma^A\\partial_A)^2=\\tfrac12\\lbrace\\Gamma^A,\\Gamma^B\\rbrace\\partial_A\\partial_B=\\eta^{AB}\\partial_A\\partial_B=\\Box$, hence')
    d.eq(r'\big(i\,\Gamma^A\partial_A+m\big)\big(i\,\Gamma^A\partial_A-m\big)=-\big(\Box+m^2\big)\,1_{16}:')
    d.p('every component of a solution obeys the 7+1 Klein–Gordon equation $(\\Box+m^2)\\psi_a=0$. The equation is linear, so it reads '
        'the same for operator-valued, Grassmann-valued or ordinary complex components; 7+1.nb verifies the identities for 16 '
        'arbitrary functions $\\psi_a(x_0,\\dots,x_7)$.')
    d.h2('4.3 Hamiltonian form')
    d.p('Multiplying by $\\Gamma^0$ from the left ($\\Gamma^0\\Gamma^0=1_{16}$):')
    d.eq(r'i\,\partial_0\psi=h\,\psi,\qquad h=-i\,\alpha_i\,\partial_i+\beta\,m,\qquad '
         r'\Gamma^0\big(i\Gamma^A\partial_A-m\big)\psi=\big(i\partial_0-h\big)\psi .')
    d.p('$\\alpha_i$ and $\\beta$ are real symmetric and $-i\\partial_i$ is Hermitian, so $h$ is Hermitian: the evolution is unitary and '
        'the charge $Q=\\int\\psi^\\dagger\\psi\\,d^7x$ is conserved.')
    d.h2('4.4 Lagrangian and conserved current')
    d.eq(r'\mathcal L_0=\bar\psi\big(i\,\Gamma^A\partial_A-m\big)\psi,\qquad j^A=\bar\psi\,\Gamma^A\psi,\qquad \partial_Aj^A=0 .')
    d.p('Conservation uses the Dirac equation and its adjoint. The Hermitian conjugate of $(i\\Gamma^A\\partial_A-m)\\psi=0$ is '
        '$-i\\partial_A\\psi^\\dagger(\\Gamma^A)^\\dagger-m\\psi^\\dagger=0$; with $(\\Gamma^A)^\\dagger=\\Gamma^0\\Gamma^A\\Gamma^0$ and '
        '$\\psi^\\dagger=\\bar\\psi\\Gamma^0$ this is')
    d.eq(r'-i\,\partial_A\bar\psi\,\Gamma^A-m\,\bar\psi=0,\qquad\text{so}\qquad '
         r'\partial_A\big(\bar\psi\Gamma^A\psi\big)=(\partial_A\bar\psi)\Gamma^A\psi+\bar\psi\Gamma^A\partial_A\psi=(im\bar\psi)\psi+\bar\psi(-im\psi)=0 .')
    d.p('The charge density is $j^0=\\psi^\\dagger\\psi$ and the spatial current $j^i=\\psi^\\dagger\\alpha_i\\psi$.')

# =========================================================================================================
@section
def sec5(d, D):
    d.h1('5. Plane waves and the real spinors $u_s$, $v_s$')
    d.h2('5.1 The momentum-space Hamiltonian')
    d.p('For a plane wave $e^{-i(Ex_0-\\vec p\\cdot\\vec x)}$ the operator $-i\\partial_i$ becomes $p^i$ and $h$ becomes the REAL '
        'symmetric 16×16 matrix')
    d.eq(r'h(\vec p)=p^i\alpha_i+m\beta=\begin{pmatrix}0&M(\vec p)\\M(\vec p)^{\mathsf T}&0\end{pmatrix},\qquad '
         r'M(\vec p)=m\,1_8+p^i\tau^{O}_i\quad(\text{real }8\times8),\qquad M(-\vec p)=M(\vec p)^{\mathsf T}.')
    d.p('Because the $\\tau^{O}_i$ are antisymmetric and anticommute, $(p^i\\tau^{O}_i)(p^j\\tau^{O}_j)^{\\mathsf T}=-(p^i\\tau^{O}_i)^2=\\vec p^{\\,2}1_8$ and')
    d.eq(r'M M^{\mathsf T}=M^{\mathsf T}M=E^2\,1_8,\qquad h(\vec p)^2=E^2\,1_{16},\qquad E=\sqrt{m^2+\vec p^{\,2}}.')
    d.h2('5.2 Real spinors')
    d.p('The eigenvalues of $h(\\vec p)$ are $\\pm E$, eight times each, with REAL eigenvectors: for $s=1,\\dots,8$')
    d.align([r'u_s(\vec p)&=\frac{1}{\sqrt E}\begin{pmatrix}E\,e_s\\ M^{\mathsf T}e_s\end{pmatrix},\qquad h(\vec p)\,u_s=+E\,u_s,',
             r'v_s(\vec p)&=\frac{1}{\sqrt E}\begin{pmatrix}E\,e_s\\ -M\,e_s\end{pmatrix},\qquad h(-\vec p)\,v_s=-E\,v_s,',
             r'u_s^{\mathsf T}u_r&=v_s^{\mathsf T}v_r=2E\,\delta_{sr},\qquad u_s(\vec p)^{\mathsf T}v_r(-\vec p)=0 .'])
    d.p('With the 8-momentum $p=(E,\\vec p)$ and the real matrix $\\not p=\\Gamma_Ap^A=E\\,\\Gamma_0+p^i\\Gamma_i$ these are the momentum-space '
        'Dirac equations')
    d.eq(r'(\not p-m)\,u_s(\vec p)=0,\qquad (\not p+m)\,v_s(\vec p)=0,')
    d.p('and the plane waves $u_s(\\vec p)\\,e^{-i(Ex_0-\\vec p\\cdot\\vec x)}$ (positive energy) and $v_s(\\vec p)\\,e^{+i(Ex_0-\\vec p\\cdot\\vec x)}$ '
        '(negative energy) solve $(i\\Gamma^A\\partial_A-m)\\psi=0$. 7+1.nb proves all of this for a completely symbolic momentum '
        '$\\vec p=(p_1,\\dots,p_7)$.')
    if D['U5'] is not None:
        d.p('**Example** (printed by 7+1.nb): $\\vec p=(2,2,4,0,0,0,0)$, $m=1$, $E=5$. The eight spinors $u_s$ are the columns of')
        d.eq(r'\sqrt5\,\big(u_1,\dots,u_8\big)=%s,' % pmat(D['U5']))
        d.p('and $h(\\vec p)\\,u_s=5\\,u_s$.')
    d.h2('5.3 Spin sums, completeness and the diagonalization of $h$')
    d.p('Since the spinors are real, $\\bar u_s=u_s^{\\mathsf T}\\Gamma^0$ and')
    d.align([r'\sum_{s=1}^{8}u_s\,\bar u_s&=\not p+m,\qquad \sum_{s=1}^{8}v_s\,\bar v_s=\not p-m,',
             r'\sum_{s=1}^{8}u_s(\vec p)\,u_s(\vec p)^{\mathsf T}&+\sum_{s=1}^{8}v_s(-\vec p)\,v_s(-\vec p)^{\mathsf T}=2E\,1_{16}.'])
    d.p('Equivalently the real orthogonal matrix')
    d.eq(r'U(\vec p)=\frac{1}{\sqrt{2E}}\big(u_1(\vec p),\dots,u_8(\vec p),\,v_1(-\vec p),\dots,v_8(-\vec p)\big),\qquad '
         r'U^{\mathsf T}U=1_{16},\qquad U^{\mathsf T}h(\vec p)\,U=\begin{pmatrix}E\,1_8&0\\0&-E\,1_8\end{pmatrix}')
    d.p('diagonalizes $h(\\vec p)$; this is what makes the mode expansion of section 6.2 work.')

# =========================================================================================================
@section
def sec6(d, D):
    d.h1('6. Grassmann variables, quantization, charge conjugation, Lorentz covariance')
    d.h2('6.1 Grassmann algebra')
    d.p('Classically the components of dirac16complex are Grassmann numbers: generators $\\theta_1,\\theta_2,\\dots$ with')
    d.eq(r'\theta_k\theta_l=-\theta_l\theta_k\qquad(\text{so }\theta_k^2=0).')
    d.p('An element is a linear combination of ordered monomials $\\theta_{k_1}\\theta_{k_2}\\cdots\\theta_{k_r}$ ($k_1<\\dots<k_r$; in 7+1.nb '
        '`grass[{k1, ..., kr}]`, with `grass[{}]` $=1$ and $\\theta_k$ = `θg[k]`). The product of two monomials is $0$ if they share a '
        'generator, and otherwise the sorted monomial times the sign of the sorting permutation (`gMul`). The left derivative '
        '$\\partial^{L}/\\partial\\theta_k$ (`gD`) moves $\\theta_k$ to the front and removes it:')
    d.eq(r'\frac{\partial^{L}}{\partial\theta_k}\big(\theta_{k_1}\cdots\theta_{k_r}\big)=(-1)^{j-1}\,\theta_{k_1}\cdots\widehat{\theta_{k_j}}\cdots\theta_{k_r}\quad'
         r'\text{if }k=k_j,\qquad\text{e.g.}\quad \frac{\partial^{L}}{\partial\theta_2}\big(\theta_1\theta_2\theta_3\big)=-\theta_1\theta_3 ,')
    d.p('where the hat means omission. **Check of current conservation with a Grassmann-valued solution.** Take three plane-wave '
        'solutions with $m=1$,')
    d.align([r'U_1&=u_1(\vec p_1)\,e^{-i(5x_0-\vec p_1\cdot\vec x)},\quad U_2=v_3(\vec p_3)\,e^{+i(3x_0-\vec p_3\cdot\vec x)},\quad '
             r'U_3=u_5(\vec 0)\,e^{-ix_0},',
             r'\vec p_1&=(2,2,4,0,0,0,0),\qquad \vec p_3=(0,0,0,2,2,0,0),'])
    d.p('and the Grassmann-valued field and its adjoint')
    d.eq(r'\psi=\theta_1U_1+\theta_2U_2+\theta_3U_3,\qquad \bar\psi=\bar\theta_1\,U_1^\dagger\Gamma^0+\bar\theta_2\,U_2^\dagger\Gamma^0+\bar\theta_3\,U_3^\dagger\Gamma^0,'
         r'\qquad \bar\theta_k=\theta_{3+k}.')
    d.p('7+1.nb verifies $\\psi_a\\psi_b+\\psi_b\\psi_a=0$ for all $a,b$ and $\\partial_A(\\bar\\psi\\Gamma^A\\psi)=0$ in this Grassmann algebra.')
    d.h2('6.2 Mode expansion and canonical anticommutators')
    d.p('In a box of volume $V$ with periodic boundary conditions the quantized field is')
    d.eq(r'\psi(x_0,\vec x)=\sum_{\vec p}\sum_{s=1}^{8}\frac{1}{\sqrt{2E\,V}}\Big[b_s(\vec p)\,u_s(\vec p)\,e^{-i(Ex_0-\vec p\cdot\vec x)}'
         r'+d_s^\dagger(\vec p)\,v_s(\vec p)\,e^{+i(Ex_0-\vec p\cdot\vec x)}\Big],')
    d.eq(r'\big\lbrace b_s(\vec p),b_r^\dagger(\vec q)\big\rbrace=\big\lbrace d_s(\vec p),d_r^\dagger(\vec q)\big\rbrace=\delta_{sr}\,\delta_{\vec p\vec q},'
         r'\qquad\text{all other anticommutators of }b,b^\dagger,d,d^\dagger\text{ vanish}.')
    d.p('$b_s(\\vec p)$ annihilates a particle and $d_s^\\dagger(\\vec p)$ creates an antiparticle, each with 8 spin states. The '
        'completeness relation of section 5.3 turns the mode algebra into the canonical anticommutators')
    d.align([r'\big\lbrace\psi_a(x_0,\vec x),\psi_b^\dagger(x_0,\vec y)\big\rbrace&=\delta_{ab}\,\frac1V\sum_{\vec p}e^{i\vec p\cdot(\vec x-\vec y)}'
             r'=\delta_{ab}\,\delta^7(\vec x-\vec y),',
             r'\big\lbrace\psi_a(x_0,\vec x),\psi_b(x_0,\vec y)\big\rbrace&=0\qquad(\psi\text{ contains only }b\text{ and }d^\dagger).'])
    d.p('7+1.nb sums the mode algebra exactly for the symmetric set of five momenta $\\pm(2,2,4,0,0,0,0)$, $\\pm(0,0,0,2,2,0,0)$, '
        '$\\vec 0$ ($m=1$, $E=5,5,3,3,1$) with symbolic $\\vec x,\\vec y$, and obtains $\\delta_{ab}\\frac1V\\sum_{\\vec p}e^{i\\vec p\\cdot(\\vec x-\\vec y)}$. '
        'Because $U^{\\mathsf T}hU=\\mathrm{diag}(E,-E)$, the normal-ordered Hamiltonian and charge are')
    d.eq(r'H=\int:\psi^\dagger h\,\psi:\,d^7x=\sum_{\vec p,s}E\,\big(b_s^\dagger b_s+d_s^\dagger d_s\big),\qquad '
         r'Q=\int:\psi^\dagger\psi:\,d^7x=\sum_{\vec p,s}\big(b_s^\dagger b_s-d_s^\dagger d_s\big):')
    d.p('particles and antiparticles have the same positive energy $E=\\sqrt{m^2+\\vec p^{\\,2}}$ and opposite charge.')
    d.h2('6.3 Charge conjugation')
    d.p('Because the $\\Gamma_A$ are real, complex conjugation of the Dirac equation gives $(-i\\Gamma^A\\partial_A-m)\\psi^*=0$, and '
        'because $\\omega$ is real and anticommutes with every $\\Gamma_A$,')
    d.eq(r'\psi^{c}=\omega\,\psi^*:\qquad \big(i\Gamma^A\partial_A-m\big)\,\omega\psi^*=\omega\,\big(-i\Gamma^A\partial_A-m\big)\psi^*=0 .')
    d.p('For the quantized field $\\psi^{c}=\\omega\\,(\\psi^\\dagger)^{\\mathsf T}$ exchanges particles and antiparticles; in momentum space')
    d.eq(r'(\not p+m)\,\omega\,u_s(\vec p)=0,\qquad \omega\,u_s(\vec p)=\sum_{r=1}^{8}v_r(\vec p)\Big(-\frac{M(\vec p)^{\mathsf T}}{E}\Big)_{rs}.')
    d.p('Applied twice, $(\\psi^{c})^{c}=\\omega\\omega\\psi=-\\psi$: the Majorana condition $\\psi^{c}=\\psi$ has no non-zero solution with '
        '16 components. (A real MASSIVE spinor field in 7+1 dimensions needs 32 real components, the quaternionic module '
        '$\\mathbb H^8=\\mathbb R^{32}$ of $Cl(7,1)\\cong\\mathbb H(8)$; real massless fields exist with 16 components, because '
        '$\\Gamma^A\\partial_A\\psi=0$ is a real equation.)')
    d.h2('6.4 Lorentz covariance')
    d.p('The generators $\\Sigma_{AB}=\\tfrac14(\\Gamma_A\\Gamma_B-\\Gamma_B\\Gamma_A)$ of Spin(1,7) are real. A boost along $x_1$ with '
        'rapidity $\\beta_{\\rm b}$ is')
    d.align([r'\mathcal B(\beta_{\rm b})&=e^{\beta_{\rm b}\Sigma_{01}}=\cosh\tfrac{\beta_{\rm b}}2\,1_{16}+\sinh\tfrac{\beta_{\rm b}}2\,\Gamma_0\Gamma_1,',
             r'\mathcal B\,\Gamma_K\,\mathcal B^{-1}&=\sum_{B}L_{BK}\,\Gamma_B,\qquad L_{BK}=\tfrac1{16}\mathrm{tr}\big(\eta_{BB}\Gamma_B\,\mathcal B\,\Gamma_K\,\mathcal B^{-1}\big),'])
    d.eq(r'L=\begin{pmatrix}\cosh\beta_{\rm b}&-\sinh\beta_{\rm b}&0\\-\sinh\beta_{\rm b}&\cosh\beta_{\rm b}&0\\0&0&1_6\end{pmatrix},\qquad L^{\mathsf T}\eta L=\eta .')
    d.p('If $\\psi(x)$ solves the Dirac equation, so does $\\psi\'(x)=\\mathcal B\\,\\psi(L^{-1}x)$, and $\\mathcal B\\,u_s(\\vec p)$ is a '
        'positive-energy spinor of the boosted momentum $p\'=Lp$. Example checked in 7+1.nb: $\\beta_{\\rm b}=2\\log2$ '
        '($\\cosh\\frac{\\beta_{\\rm b}}2=\\frac54$, $\\sinh\\frac{\\beta_{\\rm b}}2=\\frac34$), $p=(5,2,2,4,0,0,0,0)$, $m=1$:')
    d.eq(r'p^{\prime}=Lp=\Big(\frac{55}{8},-\frac{41}{8},2,4,0,0,0,0\Big),\qquad p^{\prime}\cdot p^{\prime}=1,\qquad (\not p^{\,\prime}-m)\,\mathcal B\,u_s(\vec p)=0\quad(s=1,\dots,8).')

# =========================================================================================================
@section
def sec7(d, D):
    d.h1('7. Chirality and the two coupled 8-component equations')
    d.h2('7.1 No real chirality matrix in 7+1 dimensions')
    d.p('A chirality matrix must anticommute with every Dirac matrix and square to $1_{16}$. The REAL matrices $Z$ with '
        '$Z\\Gamma_A=-\\Gamma_AZ$ for $A=0,\\dots,7$ are exactly the multiples of $\\omega$ (a 255-rank linear system for the 256 entries '
        'of $Z$, solved in 7+1.nb), and $(c\\,\\omega)^2=-c^2\\,1_{16}$. Hence there is no real chirality matrix; chirality needs')
    d.eq(r'\chi=i\,\omega=\begin{pmatrix}0&-i\,1_8\\ i\,1_8&0\end{pmatrix},\qquad \chi^\dagger=\chi,\qquad \chi^2=1_{16},\qquad '
         r'\chi\,\Gamma_A=-\Gamma_A\,\chi,\qquad \chi\,\Sigma_{AB}=\Sigma_{AB}\,\chi,')
    d.p('so chirality is Lorentz invariant. The chiral projections are complex (the Dirac matrices stay real):')
    d.eq(r'P_L=\tfrac12\big(1_{16}-\chi\big),\qquad P_R=\tfrac12\big(1_{16}+\chi\big),\qquad P_L+P_R=1_{16},\quad P_L^2=P_L,\quad P_R^2=P_R,\quad P_LP_R=0,')
    d.eq(r'\Gamma_A\,P_L=P_R\,\Gamma_A,\qquad P_L^\dagger\,\Gamma^0=\Gamma^0\,P_R,\qquad \mathrm{rank}\,P_L=\mathrm{rank}\,P_R=8 .')
    d.p('(Mathematica: $\\chi$ = `χ17`, $P_L$ = `PL17`, $P_R$ = `PR17`.)')
    d.h2('7.2 Chiral components')
    d.p('The eigenvectors of $\\chi$ give two 16×8 isometries (`EL`, `ER`) and the unitary matrix $W$ (`Wch`):')
    d.eq(r'E_L=\frac1{\sqrt2}\begin{pmatrix}1_8\\-i\,1_8\end{pmatrix},\quad E_R=\frac1{\sqrt2}\begin{pmatrix}-i\,1_8\\1_8\end{pmatrix},\qquad '
         r'\chi E_L=-E_L,\quad \chi E_R=E_R,')
    d.eq(r'W=\big(E_L,E_R\big),\qquad W^\dagger W=1_{16},')
    d.eq(r'E_L^\dagger E_L=E_R^\dagger E_R=1_8,\qquad E_L^\dagger E_R=0,\qquad E_LE_L^\dagger=P_L,\qquad E_RE_R^\dagger=P_R .')
    d.p('The chiral (Weyl) components of the field are the 8-component fields')
    d.eq(r'\phi_L=E_L^\dagger\psi=\frac{\psi_\uparrow+i\,\psi_\downarrow}{\sqrt2},\qquad \phi_R=E_R^\dagger\psi=\frac{i\,\psi_\uparrow+\psi_\downarrow}{\sqrt2},')
    d.eq(r'P_L\psi=E_L\phi_L,\qquad P_R\psi=E_R\phi_R,\qquad \psi=E_L\phi_L+E_R\phi_R .')
    d.h2('7.3 The chiral form of the Dirac equation')
    d.p('The blocks of the Dirac matrices between the chiral subspaces are')
    d.eq(r'E_L^\dagger\beta E_L=E_R^\dagger\beta E_R=0,\quad E_L^\dagger\beta E_R=E_R^\dagger\beta E_L=1_8,\qquad '
         r'E_L^\dagger\alpha_iE_L=-\sigma_i,\quad E_R^\dagger\alpha_iE_R=\sigma_i,\quad E_L^\dagger\alpha_iE_R=0,')
    d.p('with $\\sigma_i=i\\tau^{O}_i$, so $W$ brings $h(\\vec p)$ to Weyl form:')
    d.eq(r'W^\dagger h(\vec p)\,W=\begin{pmatrix}-\sigma\cdot\vec p&m\,1_8\\m\,1_8&\sigma\cdot\vec p\end{pmatrix}.')
    d.p('Projecting the Dirac equation with $E_L^\\dagger\\Gamma^0$ and $E_R^\\dagger\\Gamma^0$ gives, for arbitrary $\\psi$,')
    d.align([r'E_L^\dagger\,\Gamma^0\big(i\Gamma^A\partial_A-m\big)\psi&=\big(i\partial_0+\tau^{O}_i\partial_i\big)\phi_L-m\,\phi_R,',
             r'E_R^\dagger\,\Gamma^0\big(i\Gamma^A\partial_A-m\big)\psi&=\big(i\partial_0-\tau^{O}_i\partial_i\big)\phi_R-m\,\phi_L,'])
    d.p('so the 16-component Dirac equation is equivalent to the two coupled 8-component equations')
    d.align([r'\big(i\,\partial_0+\tau^{O}_i\,\partial_i\big)\,\phi_L&=m\,\phi_R,',
             r'\big(i\,\partial_0-\tau^{O}_i\,\partial_i\big)\,\phi_R&=m\,\phi_L .'])
    d.p('Only the REAL 8×8 matrices $\\tau^{O}_i$ occur (because $\\sigma_i(-i\\partial_i)=\\tau^{O}_i\\partial_i$); the only $i$ is the one '
        'in $i\\partial_0$. With $\\sigma^A=(1_8,\\sigma_i)$ and $\\bar\\sigma^A=(1_8,-\\sigma_i)$ the covariant form is')
    d.eq(r'i\,\bar\sigma^A\partial_A\,\phi_L=m\,\phi_R,\qquad i\,\sigma^A\partial_A\,\phi_R=m\,\phi_L .')
    d.p('The mass couples the two chiralities; for $m=0$ the equations decouple into two independent 8-component Weyl equations. Each '
        '8-component field obeys the Klein–Gordon equation, because')
    d.eq(r'\big(i\partial_0-\tau^{O}_i\partial_i\big)\big(i\partial_0+\tau^{O}_j\partial_j\big)=-\partial_0^2-\tau^{O}_i\tau^{O}_j\partial_i\partial_j=-\Box\,1_8 .')
    d.p('For a plane wave $e^{-i(Ex_0-\\vec p\\cdot\\vec x)}$ ($i\\partial_0\\to E$, $\\tau^{O}_i\\partial_i\\to i\\,\\tau^{O}\\cdot\\vec p=\\sigma\\cdot\\vec p$) '
        'the chiral equations read $(E+\\sigma\\cdot\\vec p)\\phi_L=m\\phi_R$ and $(E-\\sigma\\cdot\\vec p)\\phi_R=m\\phi_L$; 7+1.nb checks them '
        'for the eight spinors $u_s$ of the example of section 5.2.')
    d.h2('7.4 Bilinears in chiral form')
    d.p('With $\\kappa=\\phi_L^\\dagger\\phi_R$ (a complex scalar):')
    d.align([r'\bar\psi\psi&=\phi_L^\dagger\phi_R+\phi_R^\dagger\phi_L=\kappa+\kappa^*,\qquad \bar\psi\,i\chi\,\psi=i\big(\kappa-\kappa^*\big),',
             r'\bar\psi\Gamma^0\psi&=\phi_L^\dagger\phi_L+\phi_R^\dagger\phi_R,\qquad \bar\psi\Gamma^i\psi=-\phi_L^\dagger\sigma_i\phi_L+\phi_R^\dagger\sigma_i\phi_R,',
             r'\bar\psi\Gamma^0\chi\psi&=-\phi_L^\dagger\phi_L+\phi_R^\dagger\phi_R,\qquad \bar\psi\Gamma^i\chi\psi=\phi_L^\dagger\sigma_i\phi_L+\phi_R^\dagger\sigma_i\phi_R,',
             r'E_L^\dagger\beta\,i\chi\,E_R&=i\,1_8,\quad E_R^\dagger\beta\,i\chi\,E_L=-i\,1_8,\quad E_L^\dagger\chi E_L=-1_8,\quad E_R^\dagger\chi E_R=1_8,\quad '
             r'E_{L,R}^\dagger\alpha_i\chi E_{L,R}=\sigma_i .'])

# =========================================================================================================
@section
def sec8(d, D):
    d.h1('8. The self-coupled field and its 16-component Kohn–Sham theory')
    d.h2('8.1 Lagrangian, densities and Hamiltonian')
    d.p('The field couples to itself through the four Lorentz-invariant contact (point) interactions built from bilinears without '
        'derivatives, and to four real external c-number sources $\\mathsf s(x)$, $\\mathsf p(x)$, $\\mathsf v_A(x)$, $\\mathsf a_A(x)$:')
    d.align([r'\mathcal L&=\bar\psi\big(i\Gamma^A\partial_A-m\big)\psi-\bar\psi\big(\mathsf s+i\chi\,\mathsf p+\Gamma^A(\mathsf v_A+\chi\,\mathsf a_A)\big)\psi',
             r'&\quad-\frac{g_S}{2}\big(\bar\psi\psi\big)^2-\frac{g_P}{2}\big(\bar\psi\,i\chi\,\psi\big)^2-\frac{g_V}{2}\big(\bar\psi\Gamma^A\psi\big)\big(\bar\psi\Gamma_A\psi\big)'
             r'-\frac{g_A}{2}\big(\bar\psi\Gamma^A\chi\psi\big)\big(\bar\psi\Gamma_A\chi\psi\big).'])
    d.p('The four densities are')
    d.align([r'\rho_S&=\bar\psi\psi\ \ (\text{scalar}),\qquad\qquad \rho_P=\bar\psi\,i\chi\,\psi\ \ (\text{pseudoscalar}),',
             r'j^A&=\bar\psi\,\Gamma^A\psi\ \ (\text{vector}),\qquad j_5^A=\bar\psi\,\Gamma^A\chi\,\psi\ \ (\text{axial vector}),'])
    d.p('with the charge density $j^0=\\psi^\\dagger\\psi$; a lower index is $j_A=\\eta_{AA}j^A$, so '
        '$j^Aj_A=(j^0)^2-\\sum_i(j^i)^2$. All four are real (Hermitian operators), because $\\Gamma^0O$ is a Hermitian matrix for '
        '$O=1_{16},\\ i\\chi,\\ \\Gamma^A,\\ \\Gamma^A\\chi$. The couplings $g_S,g_P,g_V,g_A$ are real constants. The interaction has no time '
        'derivatives, so it enters the Hamiltonian density with the opposite sign (normal ordered):')
    d.align([r'\mathcal H&=\,:\psi^\dagger\big(-i\alpha_i\partial_i+\beta m\big)\psi:+:\bar\psi\big(\mathsf s+i\chi\,\mathsf p+\Gamma^A(\mathsf v_A+\chi\,\mathsf a_A)\big)\psi:',
             r'&\quad+\frac{g_S}{2}:\rho_S^2:+\frac{g_P}{2}:\rho_P^2:+\frac{g_V}{2}:j^Aj_A:+\frac{g_A}{2}:j_5^Aj_{5A}: .'])
    d.p('Hence $g_S<0$ is attractive (it lowers the effective mass) and $g_V>0$ is repulsive for the charge density. **Dimensions.** '
        'With $\\hbar=c=1$ the action is dimensionless; in 7+1 dimensions $\\psi$ has mass dimension $7/2$ and every coupling $g$ has '
        'mass dimension $-6$: the contact couplings are not renormalizable. The model is an effective theory. It needs a momentum '
        'cutoff $\\Lambda$ when the Dirac sea is included (section 10.4), or the no-sea approximation of relativistic mean-field and '
        'point-coupling models (section 8.4).')
    d.h2('8.2 The nonlinear field equation')
    d.p('The Euler–Lagrange equation $\\partial^L\\mathcal L/\\partial\\bar\\psi_a=0$ with the Grassmann LEFT derivative (the bilinears are '
        'Grassmann-even, so moving $\\bar\\psi_a$ to the front produces no other signs) is the nonlinear Dirac equation')
    d.align([r'&\big(i\Gamma^A\partial_A-m-\mathsf s-i\chi\,\mathsf p-\Gamma^A(\mathsf v_A+\chi\,\mathsf a_A)\big)\psi',
             r'&\qquad=g_S\big(\bar\psi\psi\big)\psi+g_P\big(\bar\psi\,i\chi\psi\big)\,i\chi\psi',
             r'&\qquad\quad+g_V\big(\bar\psi\Gamma_A\psi\big)\Gamma^A\psi+g_A\big(\bar\psi\Gamma_A\chi\psi\big)\Gamma^A\chi\psi .'])
    d.p('7+1.nb verifies it by differentiating the interaction Lagrangian in a Grassmann algebra with 32 generators '
        '($\\psi_a=\\theta_a$, $\\bar\\psi_a=\\theta_{16+a}$, $a=1,\\dots,16$): for every $a$')
    d.eq(r'\frac{\partial^L\mathcal L_{\rm int}}{\partial\bar\psi_a}=-\Big[g_S(\bar\psi\psi)\psi+g_P(\bar\psi\,i\chi\psi)\,i\chi\psi'
         r'+g_V(\bar\psi\Gamma_A\psi)\Gamma^A\psi+g_A(\bar\psi\Gamma_A\chi\psi)\Gamma^A\chi\psi\Big]_a .')
    d.h2('8.3 Densities, sources and the Hohenberg–Kohn theorem')
    d.p('Collect the densities into $n=(\\rho_S,\\rho_P,j^A,j_5^A)$ — $1+1+8+8=18$ real fields on space — and the static sources into '
        '$w=(\\mathsf s,\\mathsf p,\\mathsf v_A,\\mathsf a_A)$:')
    d.eq(r'H[w]=H_0+H_{\rm int}+\int w\cdot n\,d^7x,\qquad w\cdot n=\mathsf s\,\rho_S+\mathsf p\,\rho_P+\mathsf v_A\,j^A+\mathsf a_A\,j_5^A,\qquad '
         r'H_0=\int:\psi^\dagger\big(-i\alpha_i\partial_i+\beta m\big)\psi:\,d^7x .')
    d.p('The charge $Q=\\int j^0d^7x$ commutes with $H[w]$; the theory is formulated in the sector of fixed charge $Q=N$.')
    d.p('**Theorem (Hohenberg–Kohn, relativistic form).** Let $|\\Psi\\rangle$ be the non-degenerate ground state of $H[w]$ with charge '
        '$N$ and densities $n$. If a second source $w\'$ with a different ground state $|\\Psi\'\\rangle$ had the same densities $n$, the '
        'variational principle would give')
    d.eq(r'E=\langle\Psi|H[w]|\Psi\rangle<\langle\Psi^{\prime}|H[w]|\Psi^{\prime}\rangle=E^{\prime}+\int(w-w^{\prime})\cdot n\,d^7x,\qquad '
         r'E^{\prime}<E+\int(w^{\prime}-w)\cdot n\,d^7x,')
    d.p('and adding the two inequalities gives $E+E\'<E+E\'$, a contradiction. Hence the ground-state densities determine the ground '
        'state and every ground-state property; they determine $w$ up to changes that leave the ground state unchanged (for example '
        '$\\mathsf v_0\\to\\mathsf v_0+\\text{const}$, which only adds $\\text{const}\\times N$ to the energy). The energy is')
    d.eq(r'E[w]=\min_n\Big(F[n]+\int w\cdot n\,d^7x\Big),\qquad F[n]=\min_{|\Psi\rangle\to n}\langle\Psi|H_0+H_{\rm int}|\Psi\rangle,')
    d.p('with the universal (source-independent) functional $F$ defined by the Levy–Lieb constrained search over states with densities '
        '$n$. Standing assumptions, as usual in relativistic density-functional theory: the theory is regularized (cutoff or no-sea), '
        '$H[w]$ is bounded below in the sector $Q=N$, and the densities considered are ground-state densities of some $w$ '
        '(v-representability).')
    d.h2('8.4 The Kohn–Sham equations')
    d.p('The Kohn–Sham reference system consists of $N$ non-interacting 16-component fermions $\\varphi_k$ ($k=1,\\dots,N$; '
        '$\\int\\varphi_k^\\dagger\\varphi_l\\,d^7x=\\delta_{kl}$) in effective sources $w_{\\rm KS}=(\\mathcal S,\\mathcal P,\\mathcal V_A,\\mathcal A_A)$, '
        'chosen such that its ground state has the same densities $n$ as the interacting system. Split')
    d.align([r'F[n]&=T_s[n]+E_H[n]+E_{xc}[n],\qquad T_s=\sum_{k=1}^{N}\int\varphi_k^\dagger\big(-i\alpha_i\partial_i+\beta m\big)\varphi_k\,d^7x,',
             r'E_H&=\int\Big[\frac{g_S}{2}\rho_S^2+\frac{g_P}{2}\rho_P^2+\frac{g_V}{2}j^Aj_A+\frac{g_A}{2}j_5^Aj_{5A}\Big]d^7x\qquad(\text{Hartree, the direct term}),'])
    d.p('and $E_{xc}=F-T_s-E_H$ (exchange and correlation). Minimizing $E=T_s+\\int w\\cdot n+E_H+E_{xc}$ over orthonormal orbitals '
        '(Lagrange multipliers $\\varepsilon_k$) gives the Kohn–Sham equations')
    d.align([r'h_{\rm KS}\,\varphi_k&=\varepsilon_k\,\varphi_k,',
             r'h_{\rm KS}&=\alpha_i\big(-i\partial_i+\mathcal V_i\big)+\beta\big(m+\mathcal S\big)+\mathcal V_0+\beta\,i\chi\,\mathcal P+\chi\,\mathcal A_0+\alpha_i\chi\,\mathcal A_i,',
             r'\mathcal S&=\mathsf s+g_S\,\rho_S+\frac{\delta E_{xc}}{\delta\rho_S},\qquad \mathcal P=\mathsf p+g_P\,\rho_P+\frac{\delta E_{xc}}{\delta\rho_P},',
             r'\mathcal V_A&=\mathsf v_A+g_V\,j_A+\frac{\delta E_{xc}}{\delta j^A},\qquad \mathcal A_A=\mathsf a_A+g_A\,j_{5A}+\frac{\delta E_{xc}}{\delta j_5^A},',
             r'\rho_S&=\sum_k\bar\varphi_k\varphi_k,\quad \rho_P=\sum_k\bar\varphi_k\,i\chi\,\varphi_k,\quad j^A=\sum_k\bar\varphi_k\Gamma^A\varphi_k,\quad '
             r'j_5^A=\sum_k\bar\varphi_k\Gamma^A\chi\,\varphi_k .'])
    d.p('$\\mathcal V_A$ and $\\mathcal A_A$ carry a LOWER index ($\\mathcal V_i=-\\mathcal V^i$). Equivalently every orbital '
        '$\\varphi_k\\,e^{-i\\varepsilon_kx_0}$ solves the Dirac equation with the self-consistent potentials,')
    d.eq(r'\big(i\Gamma^A\partial_A-m-\mathcal S-i\chi\,\mathcal P-\Gamma^A(\mathcal V_A+\chi\,\mathcal A_A)\big)\varphi=0,\qquad '
         r'\Gamma^0\big(\not p-m-\mathcal S-i\chi\mathcal P-\Gamma^A(\mathcal V_A+\chi\mathcal A_A)\big)=\varepsilon\,1_{16}-h_{\rm KS}(\vec p)')
    d.p('for a plane wave with energy $\\varepsilon$ ($\\not p=\\varepsilon\\Gamma_0+p^i\\Gamma_i$). $h_{\\rm KS}$ is Hermitian for real potentials, '
        'because $\\alpha_i$, $\\beta$, $\\beta i\\chi$, $\\chi$ and $\\alpha_i\\chi$ are Hermitian.')
    d.p('**Why these are the potentials.** With $\\varphi$ and $\\varphi^*$ treated as independent variables (Wirtinger calculus), '
        'the Hartree energy density $e_H(\\varphi,\\varphi^*)$ of one orbital satisfies, for every component $a$,')
    d.eq(r'\frac{\partial e_H}{\partial\varphi_a^*}=\big(v_H\,\varphi\big)_a,\qquad v_H=\beta\,g_S\rho_S+\beta\,i\chi\,g_P\rho_P+\sum_A\Gamma^0\Gamma^A\,g_Vj_A+\sum_A\Gamma^0\Gamma^A\chi\,g_Aj_{5A},')
    d.p('i.e. $v_H$ is $h_{\\rm KS}-h$ with $\\mathcal S=g_S\\rho_S$, $\\mathcal P=g_P\\rho_P$, $\\mathcal V_A=g_Vj_A$, $\\mathcal A_A=g_Aj_{5A}$ '
        '(checked symbolically in 7+1.nb with 32 independent variables).')
    d.p('**No-sea approximation.** The occupied orbitals are the $N$ lowest POSITIVE-energy eigenvectors of $h_{\\rm KS}$; the Dirac sea is '
        'not included and its effects are absorbed in the couplings, as in relativistic mean-field and point-coupling models of nuclei.')
    d.p('**Total energy.**')
    d.eq(r'E=\sum_{k=1}^{N}\varepsilon_k-\int\Big[(\mathcal S-\mathsf s)\rho_S+(\mathcal P-\mathsf p)\rho_P+(\mathcal V_A-\mathsf v_A)j^A+(\mathcal A_A-\mathsf a_A)j_5^A\Big]d^7x+E_H+E_{xc};')
    d.p('in the Hartree approximation ($E_{xc}=0$) simply $E=\\sum_k\\varepsilon_k-E_H$ (double counting). **Self-consistency loop:** guess '
        'the potentials; solve $h_{\\rm KS}\\varphi_k=\\varepsilon_k\\varphi_k$; occupy the $N$ lowest positive levels; compute $n$; compute the new '
        'potentials; repeat until they no longer change.')

# =========================================================================================================
@section
def sec8b(d, D):
    d.h2('8.5 Exchange: Wick’s theorem for contact couplings')
    d.p('For a Slater determinant $|\\Phi\\rangle$ of $N$ orthonormal orbitals (no sea) and two vertex matrices $O_1,O_2$, all fields at '
        'the same point (contact interaction), Wick’s theorem gives')
    d.eq(r'\langle\Phi|:\big(\bar\psi O_1\psi\big)\big(\bar\psi O_2\psi\big):|\Phi\rangle=\mathrm{tr}(O_1R)\,\mathrm{tr}(O_2R)-\mathrm{tr}(O_1RO_2R),'
         r'\qquad R=\sum_{k=1}^{N}\varphi_k\,\bar\varphi_k\quad(16\times16).')
    d.p('Derivation: with mode operators $c_a$ at the point, $:\\!c_a^\\dagger c_bc_c^\\dagger c_d\\!:\\,=c_a^\\dagger c_c^\\dagger c_dc_b$ and '
        '$\\langle c_a^\\dagger c_c^\\dagger c_dc_b\\rangle=\\varrho_{ba}\\varrho_{dc}-\\varrho_{da}\\varrho_{bc}$ with '
        '$\\varrho_{xy}=\\langle c_y^\\dagger c_x\\rangle=\\sum_k\\varphi_{k,x}\\varphi_{k,y}^*$; contracting with $(\\Gamma^0O_1)_{ab}(\\Gamma^0O_2)_{cd}$ '
        'and using $R=\\varrho\\,\\Gamma^0$ gives the formula. The first term is the Hartree (direct) energy, the second the exchange '
        '(Fock) term; its minus sign comes from the anticommuting fields. 7+1.nb checks the formula for all 18 vertex pairs '
        '(1 scalar, 1 pseudoscalar, 8 vector, 8 axial) in the 3-particle Fock space of 16 modes (dimension $\\binom{16}{3}=560$), '
        'where every $c_a^\\dagger c_b$ is an explicit sparse matrix and')
    d.eq(r':\big(\psi^\dagger M_1\psi\big)\big(\psi^\dagger M_2\psi\big):\;=B(M_1)\,B(M_2)-B(M_1M_2),\qquad B(M)=\sum_{a,b}M_{ab}\,c_a^\dagger c_b,\qquad M_{1,2}=\Gamma^0O_{1,2}.')
    d.p('The exact exchange energy of the model is therefore an explicit functional of the occupied orbitals,')
    d.eq(r'E_x=-\frac{g_S}{2}\mathrm{tr}(RR)-\frac{g_P}{2}\mathrm{tr}(i\chi R\,i\chi R)-\frac{g_V}{2}\sum_A\mathrm{tr}\big(\Gamma^AR\,\Gamma_AR\big)'
         r'-\frac{g_A}{2}\sum_A\mathrm{tr}\big(\Gamma^A\chi R\,\Gamma_A\chi R\big),')
    d.p('and its variation $\\delta E_x=\\mathrm{tr}(\\Sigma_x\\,\\delta R)$ defines the exchange self-energy')
    d.eq(r'\Sigma_x=-g_S\,R-g_P\,(i\chi)R(i\chi)-g_V\sum_A\Gamma_AR\,\Gamma^A-g_A\sum_A\Gamma_A\chi R\,\Gamma^A\chi,\qquad E_x=\tfrac12\,\mathrm{tr}\big(\Sigma_xR\big).')
    d.p('In the orbital equations it enters as $\\big(i\\Gamma^A\\partial_A-m-\\Sigma_H-\\Sigma_x\\big)\\varphi=0$ with the Hartree part '
        '$\\Sigma_H=\\mathcal S+i\\chi\\mathcal P+\\Gamma^A(\\mathcal V_A+\\chi\\mathcal A_A)$. The hierarchy of approximations is: $E_{xc}=0$ '
        '(relativistic Hartree, mean field); $E_{xc}=E_x$ (relativistic Hartree–Fock, exact exchange); $E_{xc}=E_x+E_c$ with a '
        'model for the correlation energy $E_c$.')
    d.h2('8.6 Fierz identities')
    d.p('The 256 products $\\Gamma_K$ (section 3.1) are orthogonal matrices, $\\Gamma_K^{-1}=\\Gamma_K^{\\mathsf T}$, with')
    d.eq(r'\mathrm{tr}\big(\Gamma_K^{-1}\Gamma_L\big)=16\,\delta_{KL},\qquad \sum_K\big(\Gamma_K\big)_{ab}\big(\Gamma_K^{-1}\big)_{cd}=16\,\delta_{ad}\,\delta_{cb}\qquad(\text{Fierz completeness}).')
    d.p('Consequently every exchange term is a sum of direct terms (Fierz rearrangement),')
    d.eq(r'\mathrm{tr}\big(O_1RO_2R\big)=\frac1{16}\sum_K\mathrm{tr}\big(\Gamma_K^{-1}R\big)\,\mathrm{tr}\big(O_1\Gamma_KO_2R\big),')
    d.p('so for contact couplings Hartree–Fock is a Hartree theory with Fierz-transformed couplings (section 10.2 shows it for uniform '
        'matter). 7+1.nb checks these identities with all 256 products and a random complex matrix $R$.')

# =========================================================================================================
@section
def sec9(d, D):
    d.h1('9. The chiral Kohn–Sham theory (8 + 8 components)')
    d.h2('9.1 Chiral densities and sources')
    d.p('With the chiral components $\\varphi_{kL}=E_L^\\dagger\\varphi_k$ and $\\varphi_{kR}=E_R^\\dagger\\varphi_k$ of the Kohn–Sham orbitals '
        '(section 7.2) the 18 densities become one complex scalar density and two 8-currents:')
    d.align([r'\kappa&=\sum_k\varphi_{kL}^\dagger\varphi_{kR},\qquad j_L^A=\sum_k\varphi_{kL}^\dagger\bar\sigma^A\varphi_{kL},\qquad j_R^A=\sum_k\varphi_{kR}^\dagger\sigma^A\varphi_{kR},',
             r'\rho_S&=\kappa+\kappa^*=2\,\mathrm{Re}\,\kappa,\qquad \rho_P=i\big(\kappa-\kappa^*\big)=-2\,\mathrm{Im}\,\kappa,\qquad j^A=j_L^A+j_R^A,\qquad j_5^A=j_R^A-j_L^A,'])
    d.p('with $\\sigma^A=(1_8,\\sigma_i)$ and $\\bar\\sigma^A=(1_8,-\\sigma_i)$. The scalar and pseudoscalar densities pair the two '
        'chiralities; the currents do not. The sources become one complex scalar source $\\varpi=\\mathsf s+i\\mathsf p$ and two chiral vector sources:')
    d.eq(r'\mathsf s\,\rho_S+\mathsf p\,\rho_P=\varpi\,\kappa+\varpi^*\kappa^*,\qquad \mathsf v_Aj^A+\mathsf a_Aj_5^A=(\mathsf v-\mathsf a)_A\,j_L^A+(\mathsf v+\mathsf a)_A\,j_R^A .')
    d.h2('9.2 The Hartree energy in chiral variables')
    d.align([r'e_H&=\frac{g_S}{2}\big(\kappa+\kappa^*\big)^2-\frac{g_P}{2}\big(\kappa-\kappa^*\big)^2+\frac{g_V+g_A}{2}\big(j_L^Aj_{LA}+j_R^Aj_{RA}\big)+(g_V-g_A)\,j_L^Aj_{RA}',
             r'&=\frac{g_S-g_P}{2}\big(\kappa^2+\kappa^{*2}\big)+(g_S+g_P)\,\kappa\kappa^*+\frac{g_V+g_A}{2}\big(j_L^Aj_{LA}+j_R^Aj_{RA}\big)+(g_V-g_A)\,j_L^Aj_{RA}.'])
    d.p('The scalar–pseudoscalar part depends on $\\kappa$ only through $|\\kappa|^2$ exactly when $g_P=g_S$; then it is $2g_S|\\kappa|^2$, the '
        'Nambu–Jona-Lasinio form. The vector–axial part couples the two currents only through $g_V-g_A$.')
    d.h2('9.3 The chiral Kohn–Sham equations')
    d.p('In chiral components, $W^\\dagger h_{\\rm KS}W$, the Kohn–Sham equation becomes the 8+8 block system')
    d.align([r'\big[\mathcal V^L_0-\sigma_i\big(-i\partial_i+\mathcal V^L_i\big)\big]\varphi_L+\mathcal M\,\varphi_R&=\varepsilon\,\varphi_L,',
             r'\mathcal M^*\,\varphi_L+\big[\mathcal V^R_0+\sigma_i\big(-i\partial_i+\mathcal V^R_i\big)\big]\varphi_R&=\varepsilon\,\varphi_R,'])
    d.eq(r'\mathcal M=m+\mathcal S+i\,\mathcal P\quad(\text{complex Kohn–Sham mass}),\qquad \mathcal V^L_A=\mathcal V_A-\mathcal A_A,\qquad \mathcal V^R_A=\mathcal V_A+\mathcal A_A,')
    d.eq(r'W^\dagger h_{\rm KS}(\vec p)\,W=\begin{pmatrix}\mathcal V^L_0-\sigma_i(p^i+\mathcal V^L_i)&\mathcal M\,1_8\\ \mathcal M^*\,1_8&\mathcal V^R_0+\sigma_i(p^i+\mathcal V^R_i)\end{pmatrix}.')
    d.p('Since $\\sigma_i(-i\\partial_i)=\\tau^{O}_i\\partial_i$, the derivative terms contain only the real $\\tau^{O}_i$, exactly as in '
        'section 7.3; the complex mass $\\mathcal M$ couples the chiralities. The potentials are Wirtinger derivatives of the energy '
        '($\\kappa$ and $\\kappa^*$ independent):')
    d.eq(r'\mathcal M-m=\varpi+\frac{\partial(e_H+e_{xc})}{\partial\kappa},\qquad \mathcal V^L_A=(\mathsf v-\mathsf a)_A+\frac{\partial(e_H+e_{xc})}{\partial j_L^A},\qquad '
         r'\mathcal V^R_A=(\mathsf v+\mathsf a)_A+\frac{\partial(e_H+e_{xc})}{\partial j_R^A};')
    d.p('in the Hartree approximation')
    d.align([r'\mathcal M-m-\varpi&=g_S\big(\kappa+\kappa^*\big)-g_P\big(\kappa-\kappa^*\big)=g_S\,\rho_S+i\,g_P\,\rho_P,',
             r'\mathcal V^L_A-(\mathsf v-\mathsf a)_A&=(g_V+g_A)\,j_{LA}+(g_V-g_A)\,j_{RA},\qquad \mathcal V^R_A-(\mathsf v+\mathsf a)_A=(g_V+g_A)\,j_{RA}+(g_V-g_A)\,j_{LA},'])
    d.p('and, per orbital, $\\partial e_H/\\partial\\varphi_L^*=(\\mathcal V^L_0-\\sigma_i\\mathcal V^L_i)\\varphi_L+(\\mathcal M-m)\\varphi_R$, '
        '$\\partial e_H/\\partial\\varphi_R^*=(\\mathcal V^R_0+\\sigma_i\\mathcal V^R_i)\\varphi_R+(\\mathcal M-m)^*\\varphi_L$ (all verified symbolically '
        'in 7+1.nb). The densities $\\kappa$, $j_L$, $j_R$ are computed from the occupied chiral orbitals (no sea, as in section 8.4), and')
    d.eq(r'E=\sum_k\varepsilon_k-\int\Big[2\,\mathrm{Re}\big((\mathcal M-m-\varpi)\kappa\big)+\big(\mathcal V^L-\mathsf v+\mathsf a\big)_Aj_L^A+\big(\mathcal V^R-\mathsf v-\mathsf a\big)_Aj_R^A\Big]d^7x+E_H+E_{xc}.')
    d.h2('9.4 Chiral symmetry')
    d.p('Because $\\chi=i\\omega$, the chiral transformation is a REAL rotation of the 16 components:')
    d.eq(r'\psi\to e^{i\theta\chi}\psi=\big(\cos\theta\,1_{16}-\sin\theta\,\omega\big)\psi,\qquad \varphi_L\to e^{-i\theta}\varphi_L,\quad \varphi_R\to e^{i\theta}\varphi_R,\quad \kappa\to e^{2i\theta}\kappa .')
    d.p('The currents $j_L$, $j_R$ (hence $j$ and $j_5$) are invariant, $\\big(e^{i\\theta\\chi}\\big)^\\dagger\\beta\\,e^{i\\theta\\chi}=\\beta\\,(\\cos2\\theta+i\\sin2\\theta\\,\\chi)$, '
        'so $(\\rho_S,\\rho_P)$ rotate by the angle $2\\theta$, and')
    d.eq(r'E_H\big(e^{i\theta\chi}\psi\big)-E_H(\psi)=\frac{g_S-g_P}{2}\Big[\big(e^{4i\theta}-1\big)\kappa^2+\big(e^{-4i\theta}-1\big)\kappa^{*2}\Big]:')
    d.p('the interaction is chirally ($U(1)_A$) symmetric if and only if $g_P=g_S$ (checked in 7+1.nb with $\\cos\\theta=\\frac35$, $\\sin\\theta=\\frac45$). '
        'The mass term $m(\\kappa+\\kappa^*)$ of $T_s$ breaks the symmetry explicitly. For $m=0$, $g_P=g_S$ and $\\varpi=0$ the whole chiral '
        'Kohn–Sham theory is invariant: with $\\kappa=0$ the chiral equations decouple into separate 8-component equations for $\\varphi_L$ and '
        '$\\varphi_R$, while a self-consistent solution with $\\kappa\\neq0$ breaks the symmetry spontaneously (section 10.4).')

# =========================================================================================================
@section
def sec10(d, D):
    hs, h1, hf, cu, nj = D['hs'], D['h1'], D['hf'], D['cu'], D['nj']
    d.h1('10. Worked examples')
    d.h2('10.1 Uniform matter in the Hartree approximation (no sea)')
    d.p('Static, uniform, spin-saturated matter at rest, without external sources. By symmetry the Kohn–Sham potentials are constants, '
        '$\\mathcal S=m^*-m$ and $\\mathcal V_0$, with $\\mathcal P=\\mathcal A_A=\\mathcal V_i=0$. The orbitals are plane waves '
        '$u_s(\\vec p)\\,e^{i\\vec p\\cdot\\vec x}/\\sqrt{2E^*V}$ with the effective mass $m^*$, $E^*=\\sqrt{\\vec p^{\\,2}+m^{*2}}$, eigenvalues '
        '$\\varepsilon=\\mathcal V_0+E^*$, and all 8 spin states filled up to the Fermi momentum $k_F$. The unit sphere $S^6\\subset\\mathbb R^7$ '
        'has area $|S^6|=2\\pi^{7/2}/\\Gamma_{\\rm E}(\\tfrac72)=16\\pi^3/15$ ($\\Gamma_{\\rm E}$ is Euler’s Gamma function, '
        '$\\Gamma_{\\rm E}(\\tfrac72)=\\tfrac{15}{8}\\sqrt\\pi$), so with 8 spin states')
    d.eq(r'8\int\frac{d^7k}{(2\pi)^7}\,f(|\vec k|)=c_7\int_0^\infty k^6f(k)\,dk,\qquad c_7=\frac{8\,|S^6|}{(2\pi)^7}=\frac{1}{15\pi^4},')
    d.align([r'\rho&=j^0=c_7\frac{k_F^7}{7}=\frac{k_F^7}{105\pi^4},\qquad \rho_S=c_7\int_0^{k_F}\frac{k^6\,m^*}{\sqrt{k^2+m^{*2}}}\,dk,\qquad '
             r'\varepsilon_{\rm kin}=c_7\int_0^{k_F}k^6\sqrt{k^2+m^{*2}}\,dk,'])
    d.p('($\\rho_P=0$, $j_5=0$, $j^i=0$). The occupied plane waves give the density matrix $R=\\big(\\rho_S\\,1_{16}+\\rho\\,\\Gamma_0\\big)/16$, '
        'because $\\tfrac12\\sum_s\\big[u_s(\\vec p)\\bar u_s(\\vec p)+u_s(-\\vec p)\\bar u_s(-\\vec p)\\big]/(2E)=(E\\Gamma_0+m)/(2E)$. The integrals '
        'have the closed forms (printed by 7+1.nb and checked by differentiation)')
    d.align([r'\int_0^{k_F}\frac{k^6\,m^*}{\sqrt{k^2+m^{*2}}}\,dk&=\frac{m^*}{48}\Big[k_F\sqrt{k_F^2+m^{*2}}\,\big(8k_F^4-10k_F^2m^{*2}+15m^{*4}\big)',
             r'&\qquad\qquad-15\,m^{*6}\,\mathrm{artanh}\frac{k_F}{\sqrt{k_F^2+m^{*2}}}\Big],',
             r'\int_0^{k_F}k^6\sqrt{k^2+m^{*2}}\,dk&=\frac{1}{384}\Big[k_F\sqrt{k_F^2+m^{*2}}\,\big(48k_F^6+8k_F^4m^{*2}-10k_F^2m^{*4}+15m^{*6}\big)',
             r'&\qquad\qquad-15\,m^{*8}\,\mathrm{artanh}\frac{k_F}{\sqrt{k_F^2+m^{*2}}}\Big].'])
    d.p('The Hartree self-consistency conditions, the energy density and the Fermi energy are')
    d.align([r'm^*&=m+g_S\,\rho_S(m^*),\qquad \mathcal V_0=g_V\,\rho,',
             r'\varepsilon&=\varepsilon_{\rm kin}(m^*)-(m^*-m)\,\rho_S+\frac{g_S}{2}\rho_S^2+\frac{g_V}{2}\rho^2=\varepsilon_{\rm kin}(m^*)-\frac{(m^*-m)^2}{2g_S}+\frac{g_V}{2}\rho^2,',
             r'\varepsilon_F&=\mathcal V_0+\sqrt{k_F^2+m^{*2}} .'])
    d.p('The energy density equals the sum of the occupied eigenvalues minus the double counting, $\\varepsilon=\\mathcal V_0\\rho+\\varepsilon_{\\rm kin}-\\tfrac{g_S}{2}\\rho_S^2-\\tfrac{g_V}{2}\\rho^2$. '
        'It is stationary in $m^*$, $\\partial\\varepsilon/\\partial m^*=\\rho_S-(m^*-m)/g_S=0$ being the gap equation (using '
        '$d\\varepsilon_{\\rm kin}/dm^*=\\rho_S$), so $d\\varepsilon/dk_F=\\partial\\varepsilon/\\partial k_F=c_7k_F^6\\,(\\sqrt{k_F^2+m^{*2}}+g_V\\rho)$ and, with '
        '$d\\rho/dk_F=c_7k_F^6$, the chemical potential $\\mu$ is')
    d.eq(r'\mu=\frac{d\varepsilon}{d\rho}=\varepsilon_F\qquad\text{at every density},\qquad \frac{d}{dk_F}\Big(\frac{\varepsilon}{\rho}\Big)=\frac{c_7k_F^6}{\rho}\Big(\mu-\frac{\varepsilon}{\rho}\Big):')
    d.p('at the saturation point (the minimum of the energy per particle $E/A=\\varepsilon/\\rho$) one has $E/A=\\varepsilon_F$ — the '
        'Hugenholtz–Van Hove theorem. **Example** (units $m=1$): $g_S=-10^5$, $g_V=10^4$, $g_P=g_A=0$. Saturation is found by solving '
        '$\\varepsilon/\\rho=\\varepsilon_F$ for $k_F$ (40-digit arithmetic in 7+1.nb, 30 digits in Python):')
    d.table(['quantity', 'saturation point', '$k_F=1$'], [
        ['$k_F$', '$%s$' % num(hs['kF0'], 15), '$1$'],
        ['$\\rho$', '$%s$' % num(hs['rho0'], 15), '$%s$' % num(sp.Integer(1)/(105*sp.pi**4), 15)],
        ['$m^*$', '$%s$' % num(hs['mstar'], 15), '$%s$' % num(h1['mstar'], 15)],
        ['$\\rho_S$', '$%s$' % num(hs['rhoS'], 15), '—'],
        ['$\\mathcal V_0=g_V\\rho$', '$%s$' % num(hs['V0'], 15), '—'],
        ['$E/A-m$', '$%s$' % num(hs['E/A - m'], 15), '$%s$' % num(h1['E/A - m'], 15)],
        ['$\\varepsilon_F$', '$%s$' % num(hs['epsF'], 15), '$%s$' % num(h1['epsF'], 15)]],
        widths=[0.26, 0.37, 0.37])
    d.p('At the saturation point $E/A=1+(E/A-m)=\\varepsilon_F$ (to 25 digits) and the numerical derivative $d\\varepsilon/d\\rho$ equals $\\varepsilon_F$; '
        'at $k_F=1$ the matter is not saturated ($E/A-m>0$) and still $d\\varepsilon/d\\rho=\\varepsilon_F$. The energy per particle is lower than at '
        '$0.95\\,k_{F}$ and $1.05\\,k_{F}$ of the saturation point: the matter is bound and saturates.')
    d.h2('10.2 Uniform matter in the Hartree–Fock approximation')
    d.p('With the uniform density matrix $R=(\\rho_S1_{16}+\\rho\\Gamma_0)/16$ the exchange energy and self-energy of section 8.5 are')
    d.align([r'E_x&=-\frac{g_S}{32}\big(\rho_S^2+\rho^2\big)+\frac{g_P}{32}\big(\rho_S^2-\rho^2\big)-\frac{g_V}{32}\big(8\rho_S^2-6\rho^2\big)+\frac{g_A}{32}\big(8\rho_S^2+6\rho^2\big),',
             r'\Sigma_x&=S_x\,1_{16}+V_x\,\Gamma_0,\qquad S_x=\frac{\partial E_x}{\partial\rho_S}=\frac{\rho_S}{16}\big(-g_S+g_P-8g_V+8g_A\big),',
             r'V_x&=\frac{\partial E_x}{\partial\rho}=\frac{\rho}{16}\big(-g_S-g_P+6g_V+6g_A\big),'])
    d.p('(using $\\Gamma^A\\Gamma_A=8$ and $\\Gamma^A\\Gamma_0\\Gamma_A=-6\\Gamma_0$), so uniform Hartree–Fock is Hartree with the Fierz-transformed couplings')
    d.eq(r'G_S=g_S+\frac{-g_S+g_P-8g_V+8g_A}{16},\qquad G_V=g_V+\frac{-g_S-g_P+6g_V+6g_A}{16},')
    d.eq(r'\frac{g_S}{2}\rho_S^2+\frac{g_V}{2}\rho^2+E_x=\frac{G_S}{2}\rho_S^2+\frac{G_V}{2}\rho^2 .')
    d.p('For $g_S=-10^5$, $g_V=10^4$, $g_P=g_A=0$: $G_S=-98750$, $G_V=20000$. At $k_F=\\tfrac34$:')
    d.table(['quantity', 'Hartree–Fock', 'Hartree'], [
        ['$m^*$', '$%s$' % num(hf['HF mstar'], 15), '$%s$' % num(hf['Hartree mstar'], 15)],
        ['$\\mathcal V_0$', '$%s$' % num(hf['HF V0'], 15), '$%s$' % num(sp.Integer(10)**4 * sp.Rational(3, 4)**7/(105*sp.pi**4), 15)],
        ['$E/A-m$', '$%s$' % num(hf['HF E/A - m'], 15), '$%s$' % num(hf['Hartree E/A - m'], 15)]],
        widths=[0.26, 0.37, 0.37])
    d.p('The Hartree–Fock self-consistency $m^*-m=g_S\\rho_S+S_x$, $\\mathcal V_0=g_V\\rho+V_x$ and $\\mu=\\varepsilon_F$ hold to 30 digits. '
        'The exchange term weakens the attraction and strengthens the repulsion: with these couplings Hartree–Fock matter at $k_F=\\frac34$ is unbound.')
    d.h2('10.3 Uniform matter in chiral form')
    d.p('For the matter of section 10.1: $\\kappa=\\rho_S/2$ (real), $j_L^0=j_R^0=\\rho/2$, $j_L^i=j_R^i=0$, $\\mathcal M=m^*$ (real), '
        '$\\mathcal V^L_0=\\mathcal V^R_0=\\mathcal V_0$. The chiral Kohn–Sham Hamiltonian $\\left(\\begin{smallmatrix}\\mathcal V_0-\\sigma\\cdot\\vec p&m^*\\\\m^*&\\mathcal V_0+\\sigma\\cdot\\vec p\\end{smallmatrix}\\right)$ '
        'satisfies $(h_\\chi-\\mathcal V_0)^2=(\\vec p^{\\,2}+m^{*2})1_{16}$: eigenvalues $\\mathcal V_0\\pm\\sqrt{\\vec p^{\\,2}+m^{*2}}$, eight times each, as in the '
        '16-component form. At saturation: $\\kappa=%s$, $j_L^0=j_R^0=%s$, $\\mathcal M=%s$, $\\mathcal V^L_0=\\mathcal V^R_0=%s$.'
        % (num(cu['kappa = rhoS/2'], 12), num(cu['jL^0 = jR^0 = rho/2'], 12), num(cu['M = m*'], 12), num(cu['V^L_0 = V^R_0 = V0'], 12)))
    d.h2('10.4 The chiral vacuum with the Dirac sea: spontaneous chiral symmetry breaking')
    d.p('Keep now the Dirac sea — all negative-energy Kohn–Sham orbitals occupied, with a momentum cutoff $|\\vec p|<\\Lambda$ — and take '
        '$g_P=g_S=g$, $\\varpi=0$, $\\mathcal V=\\mathcal A=0$, no matter. With a uniform complex mass $\\mathcal M$ the chiral Hamiltonian')
    d.eq(r'h_\chi(\vec p)=\begin{pmatrix}-\sigma\cdot\vec p&\mathcal M\,1_8\\ \mathcal M^*1_8&\sigma\cdot\vec p\end{pmatrix},\qquad h_\chi(\vec p)^2=\big(\vec p^{\,2}+|\mathcal M|^2\big)1_{16},')
    d.p('has eigenvalues $\\pm E$, $E=\\sqrt{\\vec p^{\\,2}+|\\mathcal M|^2}$, and the projector on the filled sea is '
        '$\\Pi_-(\\vec p)=\\tfrac12\\big(1_{16}-h_\\chi(\\vec p)/E\\big)$, whose RL block is $-\\mathcal M^*/(2E)\\,1_8$. Per momentum '
        '$\\kappa_{\\vec p}=\\mathrm{tr}\\,\\Pi_-^{RL}=-4\\mathcal M^*/E$, and with $|S^6|/(2\\pi)^7=1/(120\\pi^4)$')
    d.align([r'\kappa&=-4\,\mathcal M^*J(|\mathcal M|),\qquad J(M)=\int_{|\vec p|<\Lambda}\frac{d^7p}{(2\pi)^7}\frac{1}{\sqrt{\vec p^{\,2}+M^2}}=\frac{1}{120\pi^4}\int_0^\Lambda\frac{p^6\,dp}{\sqrt{p^2+M^2}},',
             r'K(M)&=\frac{1}{120\pi^4}\int_0^\Lambda p^6\sqrt{p^2+M^2}\,dp .'])
    d.p('The Hartree Kohn–Sham mass $\\mathcal M=m+\\partial e_H/\\partial\\kappa=m+2g\\kappa^*$ gives the gap equation and the vacuum energy density')
    d.align([r'\mathcal M&=m-8\,g\,J(|\mathcal M|)\,\mathcal M,',
             r'\mathcal E(\mathcal M)&=-8K(|\mathcal M|)+8J(|\mathcal M|)\,\mathrm{Re}\big[(\mathcal M-m)\mathcal M^*\big]+32\,g\,|\mathcal M|^2J(|\mathcal M|)^2,'])
    d.p('the sum of the sea eigenvalues $-8K$ minus the double counting $2\\mathrm{Re}[(\\mathcal M-m)\\kappa]$ plus $e_H=2g|\\kappa|^2$; per momentum, '
        '$\\mathrm{tr}(\\Pi_-h_0)=-8E+8\\,\\mathrm{Re}[(\\mathcal M-m)\\mathcal M^*]/E$. The stationarity condition of $\\mathcal E$ is the gap equation; for $m=0$ '
        '$d\\mathcal E/d|\\mathcal M|=8|\\mathcal M|\\,(1+8gJ)\\,(J+|\\mathcal M|J\')$. For $m=0$ a solution $\\mathcal M\\neq0$ exists if and only if '
        '$1+8gJ(|\\mathcal M|)=0$ has a root, i.e. if and only if')
    d.eq(r'g<g_c=-\frac{1}{8J(0)}=-\frac{90\pi^4}{\Lambda^6},\qquad J(0)=\frac{\Lambda^6}{720\pi^4},\qquad K(0)=\frac{\Lambda^8}{960\pi^4}.')
    d.p('For $m=0$, $\\mathcal E$ depends only on $|\\mathcal M|$: the broken vacua $\\mathcal M=|\\mathcal M|e^{i\\phi}$ are degenerate and related by '
        'chiral rotations, the phase $\\phi$ being the Goldstone direction. A small explicit mass $m>0$ selects the real positive $\\mathcal M$ '
        '($\\mathcal E(\\mathcal Me^{i\\phi})-\\mathcal E(\\mathcal M)=8Jm|\\mathcal M|(1-\\cos\\phi)>0$). **Example:** $\\Lambda=1$, $g=\\frac65g_c$:')
    d.table(['quantity', 'value'], [
        ['$g_c=-90\\pi^4$', '$%s$' % num(nj['g_c'], 15)],
        ['$g=\\frac65g_c$', '$%s$' % num(nj['g'], 15)],
        ['$|\\mathcal M|$ for $m=0$', '$%s$' % num(nj['|M| (m = 0)'], 15)],
        ['$\\kappa=-4\\mathcal MJ(\\mathcal M)$ ($\\mathcal M$ real)', '$%s$' % num(nj['kappa (m = 0, M real)'], 15)],
        ['$\\mathcal E(\\mathcal M)-\\mathcal E(0)$', '$%s$' % num(nj['E(M) - E(0)'], 15)],
        ['$\\mathcal M$ for $m=1/100$', '$%s$' % num(nj['M (m = 1/100)'], 15)]],
        widths=[0.5, 0.45])
    d.p('7+1.nb also diagonalizes $h_\\chi(\\vec p)$ at one momentum, $\\vec p=(\\frac3{10},-\\frac15,\\frac1{10},\\frac14,0,-\\frac3{20},\\frac1{20})$, with '
        'the complex mass $\\mathcal M=|\\mathcal M|e^{7i/10}$, and confirms $h_\\chi^2=E^2$, $\\Pi_-^2=\\Pi_-$, $\\mathrm{tr}\\,\\Pi_-=8$, '
        '$\\kappa_{\\vec p}=-4\\mathcal M^*/E$ and the sea energy formula.')

