@section
def sec11(d, D):
    nbinfo = D['nb']; log = D['log']; ref = D['ref']
    d.h1('11. Verification')
    d.h2('11.1 In Mathematica')
    d.p('7+1.nb was evaluated with Wolfram Language %s, by tools/run_eval.wl (all cells evaluated in a fresh kernel, then saved), in %s s, with %d message '
        'cells. Every claim is a cell `check["name", test]`; sections 7–9 contain %d of them and the whole notebook %d. All are True; '
        'the summary of section 10 prints `Length[checks]` $=%s$, `failedChecks` $=\\lbrace\\rbrace$ and `allChecksPassed` $=$ True. The checks '
        'of sections 7–9:' % (nbinfo['version'], log.get('seconds', '?'), D['messages_all'], len(D['checks79']), len(all_checks(D)),
                              D['summary10'][0] if D['summary10'] else '?'))
    rows = []
    for name, res, sec, sub in D['checks79']:
        rows.append([sub.split(' ')[0], '`' + name + '`', res])
    d.table(['§', 'check (as named in 7+1.nb)', 'result'], rows, widths=[0.07, 0.83, 0.10], small=True)
    d.h2('11.2 Independently in Python')
    d.p('tools/ref_dirac16.py recomputes everything with sympy (exact arithmetic), mpmath (30 digits) and numpy: the Dirac matrices and '
        'their properties, the Dirac and Klein–Gordon identities for 16 arbitrary functions, the real spinors, spin sums, completeness and '
        'diagonalization for a symbolic momentum, the canonical anticommutators from the mode algebra, charge conjugation, the boost, the '
        'chirality theorem (rank 255), the chiral projections and the two coupled 8-component equations, Grassmann anticommutation, current '
        'conservation and the nonlinear field equation (32-generator Grassmann algebra), the Kohn–Sham Hamiltonians and their chiral form, '
        'the Hartree potentials as Wirtinger derivatives, $U(1)_A$, the Fierz completeness and rearrangement, Wick’s theorem in the 560-dimensional '
        'Fock space, the uniform-matter exchange formulas, the uniform-matter numbers (Hartree, Hartree–Fock, saturation, Hugenholtz–Van Hove) '
        'and the chiral vacuum with the Dirac sea. It has %d boolean checks, all True.' % len(D['ref_bool']))
    d.p('tools/verify_7p1_nb.py parses the evaluated notebook and compares: every check output True; the printed spinors $\\sqrt5\\,u_s$ '
        'against Python; the printed closed forms of section 10.1, differentiated with sympy; and 23 printed numbers against '
        'tools/ref_dirac16.py, agreeing to at least 17 significant digits:')
    hs, h1, hf, cu, nj = D['hs'], D['h1'], D['hf'], D['cu'], D['nj']
    pairs = [('saturation $k_F$', hs['kF0'], ref['NUM Hartree saturation kF0']), ('saturation $\\rho$', hs['rho0'], ref['NUM Hartree rho0']),
             ('saturation $m^*$', hs['mstar'], ref['NUM Hartree m*']), ('saturation $\\rho_S$', hs['rhoS'], ref['NUM Hartree rhoS']),
             ('saturation $\\mathcal V_0$', hs['V0'], ref['NUM Hartree V0']), ('saturation $E/A-m$', hs['E/A - m'], ref['NUM Hartree E/A - m']),
             ('saturation $\\varepsilon_F$', hs['epsF'], ref['NUM Hartree eps_F']), ('$k_F=1$: $m^*$', h1['mstar'], ref['NUM Hartree kF=1: m*']),
             ('$k_F=1$: $E/A-m$', h1['E/A - m'], ref['NUM Hartree kF=1: E/A - m']), ('$k_F=1$: $\\varepsilon_F$', h1['epsF'], ref['NUM Hartree kF=1: eps_F']),
             ('HF $k_F=\\frac34$: $m^*$', hf['HF mstar'], ref['NUM HF kF=3/4: m*']), ('HF $k_F=\\frac34$: $\\mathcal V_0$', hf['HF V0'], ref['NUM HF kF=3/4: V0']),
             ('HF $k_F=\\frac34$: $E/A-m$', hf['HF E/A - m'], ref['NUM HF kF=3/4: E/A - m']), ('Hartree $k_F=\\frac34$: $m^*$', hf['Hartree mstar'], ref['NUM Hartree kF=3/4: m*']),
             ('Hartree $k_F=\\frac34$: $E/A-m$', hf['Hartree E/A - m'], ref['NUM Hartree kF=3/4: E/A - m']),
             ('chiral $\\kappa=\\rho_S/2$', cu['kappa = rhoS/2'], ref['NUM Hartree rhoS']/2), ('chiral $\\mathcal M=m^*$', cu['M = m*'], ref['NUM Hartree m*']),
             ('$g_c$', nj['g_c'], ref['NUM NJL g_c']), ('$g$', nj['g'], ref['NUM NJL g = 6/5 g_c']), ('$|\\mathcal M|$ ($m=0$)', nj['|M| (m = 0)'], ref['NUM NJL |M| (m = 0)']),
             ('$\\kappa$ ($m=0$)', nj['kappa (m = 0, M real)'], ref['NUM NJL kappa = -4 M J(|M|) (M real)']),
             ('$\\mathcal E(\\mathcal M)-\\mathcal E(0)$', nj['E(M) - E(0)'], ref['NUM NJL E(|M|) - E(0)']), ('$\\mathcal M$ ($m=\\frac1{100}$)', nj['M (m = 1/100)'], ref['NUM NJL M (m = 1/100)'])]
    rows = []
    for name, a, b in pairs:
        a = sp.Float(a, 30); b = sp.Float(b, 30)
        rel = abs(a - b)/abs(b) if b != 0 else abs(a - b)
        rows.append([name, '$%s$' % num(a, 18), '$%s$' % num(b, 18), '$%s$' % (num(rel, 2) if rel != 0 else '0')])
    d.table(['quantity', '7+1.nb (Mathematica)', 'ref_dirac16.py (Python)', 'rel. diff.'], rows, widths=[0.27, 0.29, 0.29, 0.13], small=True)

