@section
def sec12(d, D):
    d.h1('12. The notebook: sections 7–10 of 7+1.nb')
    secs = OrderedDict()
    for st, sec, sub, t in D['rows']:
        pass
    import nbparse as P, os
    nb = P.parse_notebook(D['nb']['path'])
    for dd, c in P.iter_cells(nb):
        st, content, opts = P.cell_info(c)
        if st == 'Section':
            cur = P.box_to_text(content).strip('"')
            if cur[:2] in ('7.', '8.', '9.', '10'): secs[cur] = []
            else: cur = None
        elif st == 'Subsection' and cur:
            secs[cur].append(P.box_to_text(content).strip('"'))
    d.ul(['**%s** — %s' % (k, '; '.join(v) if v else 'the four summary cells: `Length[checks]`, `failedChecks`, `allChecksPassed` and a '
          'table of all checks') for k, v in secs.items()])
    d.p('Sections 0–6 (the octonions and the Clifford algebra of 7+1 spacetime) are unchanged. The evaluated notebook as it was before '
        'sections 7–10 were appended is kept in the workspace folder backups/ (file 7+1_2026-10-26_before_dirac16complex.nb), a folder '
        'excluded from the repository by .gitignore. Section 6 summarizes the checks of sections 1–5 (it is evaluated before sections 7–9); '
        'section 10 summarizes all checks.')
    d.p('**To re-evaluate.** Open 7+1.nb in Wolfram 15.0.1, start from a fresh kernel (Evaluation ▸ Quit Kernel ▸ Local, if the kernel has been '
        'used) and choose Evaluation ▸ Evaluate Notebook (about %s seconds), or evaluate the following line in any notebook of Wolfram 15.0.1; it '
        'evaluates 7+1.nb in place in a fresh kernel, saves it and writes build/eval_log.txt:'
        % ('%.0f' % float(D['log'].get('seconds', '0') or 0)))
    d.code('Get["D:/Developer/github/7+1/tools/run_eval.wl"]')
    d.p('The Wolfram front end used is')
    d.code('C:\\Program Files\\Wolfram Research\\Wolfram\\15.0.1\\WolframNB.exe')
    d.p('The notebook itself is generated by tools/make_7p1_nb.py. The cross-check of the evaluated notebook and the independent Python '
        'checks are run with')
    d.code('python3 tools/verify_7p1_nb.py\npython3 tools/ref_dirac16.py', 'bash')
    d.p('**Main Mathematica names.** `Γ17[A]` ($\\Gamma_A$), `Γ17up[A]` ($\\Gamma^A$), `βD` ($\\beta$), `αD[i]` ($\\alpha_i$), `ω17` ($\\omega$), '
        '`χ17` ($\\chi$), `PL17`, `PR17` ($P_L,P_R$), `EL`, `ER`, `Wch` ($E_L,E_R,W$), `σW[i]` ($\\sigma_i$), `dirac16complex` ($\\psi$), '
        '`DiracEq16[ψ, m]` ($(i\\Gamma^A\\partial_A-m)\\psi$), `hD[ψ, m]` ($h\\psi$), `hp[p, m]` ($h(\\vec p)$), `uS`, `vS` ($u_s$, $v_s$), '
        '`slash17[E, p]` ($\\not p$), `grass`, `gMul`, `gD`, `θg[k]` (Grassmann algebra), `vPairs` (the 18 vertex pairs), `hKS[p]` '
        '($h_{\\rm KS}(\\vec p)$), `hChiKS[p]` (its chiral form), `EH16`, `EHchi` ($E_H$), `Exfun`, `Sigmax` ($E_x$, $\\Sigma_x$), `products256` '
        '($\\Gamma_K$), `gap7`, `eps7`, `fermi7` (uniform matter), `Jsea`, `Ksea`, `Esea`, `gcrit`, `gNJL` (Dirac sea).')

